                        sp[1] = px[1];   /* the trap */
                        sp[2] = px[2]; sp[3] = px[3]; sp[4] = px[4];   /* target, thisArg, argArray */
                        call_argv = (JSValueConst *)(sp + 2); call_argc = 3; sp += 5;
