                sf = gsf; b = gb; ctx = gb->realm;
                var_refs = gfp->u.func.var_refs;
                local_buf = arg_buf = gsf->arg_buf;
                var_buf = gsf->var_buf;
                stack_buf = gsf->var_buf + gb->var_count;
