                int cfirst, cargc; uint8_t itail;
                void *rcs = rtf->cont_state; uint8_t rck = rtf->cont_kind;
                int rfof = rtf->forof_off;   /* CONT_FOROF_NEXT: the enum_rec offset, relative to the restored caller sp */
