static const JSTrampStepDef *tramp_step_def_by_id(int id)
{
    DCHECK(id >= 0 && id < STEPDEF_COUNT, "step def id out of range");
    DCHECK(js_tramp_step_defs[id] != NULL, "a STEPDEF id with no definition — the table row is missing");
    return js_tramp_step_defs[id];
}

/* Every step state MUST begin with JSStepHdr — the driver casts the opaque state to JSStepHdr * and writes
   def/orig_c* through it, so a state that forgets gets its first field overwritten by the step-def pointer.
   That bug has now happened THREE times (JSArrayFind, JSArrayEvery, JSArraySort) and each time the corruption
   surfaced far from the cause: the last one showed up as s->obj holding &js_array_sort_def, and I misread it
   twice as a sort-semantics mismatch. A comment saying "MUST be first" did not prevent any of the three. This
   does, at compile time. Adding a state to js_tramp_step_defs without a line here is itself the omission. */
#define STEP_STATE_HDR_FIRST(T) \
    _Static_assert(offsetof(T, hdr) == 0, #T " must begin with JSStepHdr (the step driver casts to it)")
STEP_STATE_HDR_FIRST(JSArrayFind);
STEP_STATE_HDR_FIRST(JSArrayEvery);
STEP_STATE_HDR_FIRST(JSArrayReduce);
STEP_STATE_HDR_FIRST(JSArraySort);
STEP_STATE_HDR_FIRST(JSStrReplace);
STEP_STATE_HDR_FIRST(JSReRep);
STEP_STATE_HDR_FIRST(JSReMatch);
STEP_STATE_HDR_FIRST(JSStrMatch);
STEP_STATE_HDR_FIRST(JSReCtor);
STEP_STATE_HDR_FIRST(JSReMatchAll);
STEP_STATE_HDR_FIRST(JSReSplit);
STEP_STATE_HDR_FIRST(JSReSearch);
STEP_STATE_HDR_FIRST(JSJsonReviver);
STEP_STATE_HDR_FIRST(JSJsonStr);
STEP_STATE_HDR_FIRST(JSForIn);
STEP_STATE_HDR_FIRST(JSHasOwn);
STEP_STATE_HDR_FIRST(JSLookupAcc);
STEP_STATE_HDR_FIRST(JSFuncBind);
STEP_STATE_HDR_FIRST(JSIterSetter);
STEP_STATE_HDR_FIRST(JSIterHelperReturn);
STEP_STATE_HDR_FIRST(JSIntegrity);
STEP_STATE_HDR_FIRST(JSObjToString);
STEP_STATE_HDR_FIRST(JSObjToLocale);
STEP_STATE_HDR_FIRST(JSInstanceOf);
STEP_STATE_HDR_FIRST(JSImportOpts);
STEP_STATE_HDR_FIRST(JSStrCtor);
STEP_STATE_HDR_FIRST(JSStrConcat);
STEP_STATE_HDR_FIRST(JSTASlice);
STEP_STATE_HDR_FIRST(JSArrayAt);
STEP_STATE_HDR_FIRST(JSArraySearch);
STEP_STATE_HDR_FIRST(JSStrRecv);
STEP_STATE_HDR_FIRST(JSTAIdx);
STEP_STATE_HDR_FIRST(JSJsonRaw);
STEP_STATE_HDR_FIRST(JSObjDefProp);
STEP_STATE_HDR_FIRST(JSParseNum);
STEP_STATE_HDR_FIRST(JSStrSplit);
STEP_STATE_HDR_FIRST(JSArrayJoin);
STEP_STATE_HDR_FIRST(JSArrayToString);
STEP_STATE_HDR_FIRST(JSFuncCall);
STEP_STATE_HDR_FIRST(JSCoerce1);
STEP_STATE_HDR_FIRST(JSNumberFmt);
STEP_STATE_HDR_FIRST(JSNumCtor);
STEP_STATE_HDR_FIRST(JSPrimArgs);

static const JSTrampStepDef *tramp_step_def_of(JSValueConst func)
{
    JSObject *fp;
    if (JS_VALUE_GET_TAG(func) != JS_TAG_OBJECT) return NULL;
    fp = JS_VALUE_GET_OBJ(func);
    if (fp->class_id == JS_CLASS_C_FUNCTION_DATA) {
        /* a closure (Promise reaction) that DECLARED itself a step machine — its step_def, or NULL for an ordinary
           closure. The closure is then driven through the SAME do_step_tramp path as a C-function step machine, so
           an internal JS_Call to a user resolve/reject runs on the tramp and parks. */
        JSCFunctionDataRecord *s = fp->u.c_function_data_record;
        return s ? s->step_def : NULL;
    }
    if (fp->class_id == JS_CLASS_PROMISE_RESOLVE_FUNCTION
        || fp->class_id == JS_CLASS_PROMISE_REJECT_FUNCTION) {
        /* a resolving function IS a step machine — there is exactly one algorithm (27.2.1.3.2), and which of the
           two it performs is the CLASS, not a def. Its `Get(resolution, "then")` is the page's code, and the
           class `call` hook read it with JS_GetProperty from C. */
        return &js_promise_resolvefn_def;
    }
    if (fp->class_id != JS_CLASS_C_FUNCTION) return NULL;
    if (fp->u.cfunc.cproto != JS_CFUNC_step && fp->u.cfunc.cproto != JS_CFUNC_step_ctor) return NULL;
    DCHECK((unsigned)fp->u.cfunc.magic < STEPDEF_COUNT, "JS_CFUNC_STEP_DEF id is out of range");
    DCHECK(js_tramp_step_defs[fp->u.cfunc.magic] != NULL, "STEPDEF id has no table row");
    return js_tramp_step_defs[fp->u.cfunc.magic];
}

/* the same question restricted to [[Construct]]: a plain step machine is not a constructor, so `new (arr.map)`
   must still reach JS_CallConstructorInternal's TypeError rather than being driven as one. This is the construct
   side's routing predicate — it picks WHICH single implementation runs, and there is nothing left for it to
   fall back to. */
static const JSTrampStepDef *tramp_step_ctor_def_of(JSValueConst func)
{
    JSObject *fp;
    if (JS_VALUE_GET_TAG(func) != JS_TAG_OBJECT) return NULL;
    fp = JS_VALUE_GET_OBJ(func);
    if (fp->class_id != JS_CLASS_C_FUNCTION || fp->u.cfunc.cproto != JS_CFUNC_step_ctor) return NULL;
    return tramp_step_def_of(func);
}

/* 23.1.3.36 Array.prototype.toString. Stages: 0 ToObject, 1 Get(array,"join"), 2 its dispatch, 3 the result. */
static int js_array_tostring_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayToString *s = st;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        s->result = JS_UNDEFINED;
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_getprop_run(ctx, &s->hdr, s->obj, JS_ATOM_join, cb_result, &s->cb[1], out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        if (!JS_IsFunction(ctx, s->cb[1])) {
            /* step 3: a non-callable `join` falls back to the intrinsic Object.prototype.toString, whose
               @@toStringTag read is the page's. This ran it from C and said so — "a read this machine does not
               yet route" — which it now does: that intrinsic IS a machine, so this DELEGATES to it rather than
               keeping a second way to perform the same abstract operation. */
            void *inner = tramp_step_state_new(ctx, &js_obj_tostring_def, s->obj, 0, NULL, JS_UNDEFINED);
            if (!inner) return -1;
            s->hdr.stage = 9;
            s->hdr.delegate = inner;
            return 17;   /* DELEGATE */
        }
        s->cb[0] = js_dup(s->obj);
        s->hdr.stage = 3;
        *out_cb = s->cb; *out_argc = 0;
        return 3;
    }
    if (s->hdr.stage == 9) {   /* the delegated Object.prototype.toString finished; its answer is ours */
        if (JS_IsException(cb_result)) return -1;
        s->result = cb_result;
        return 0;
    }
    DCHECK(s->hdr.stage == 3, "Array.prototype.toString: unknown stage");
    s->result = cb_result;
    return 0;
}

static JSValue js_array_tostring_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayToString *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->obj);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.18 join / 23.1.3.33 toLocaleString. Stages: 0 ToObject, 1 LengthOfArrayLike, 2 ToString(separator),
   then the loop — 3 its head (the separator), 8 read element i, 4 dispatch on it, 5 the toLocaleString method,
   6 its call's result, 7 ToString(element) and append. The loop returns to 3 until i reaches len. */
static int js_array_join_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayJoin *s = st;
    int mode = s->hdr.arg;
    int locale = (mode == JOIN_ARRAY_LOCALE || mode == JOIN_TA_LOCALE);
    int is_ta = (mode == JOIN_TA || mode == JOIN_TA_LOCALE);
    JSValue str;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        string_buffer_init(ctx, &s->b, 0);
        s->sep = JS_UNDEFINED; s->el = JS_UNDEFINED; s->result = JS_UNDEFINED;
        if (is_ta) {
            JSObject *p = get_typed_array(ctx, s->hdr.this_val);
            if (!p) { s->obj = JS_UNDEFINED; return -1; }
            if (typed_array_is_oob(p)) {
                s->obj = JS_UNDEFINED;
                JS_ThrowTypeErrorArrayBufferOOB(ctx);
                return -1;
            }
            s->obj = js_dup(s->hdr.this_val);
            s->oldlen = s->len = p->u.array.count;
        } else {
            s->obj = JS_ToObject(ctx, s->hdr.this_val);
            if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        if (!is_ta) {   /* a typed array's length is its own count, not a property read */
            r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
        }
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        /* toLocaleString takes no separator: its comma is not configurable. */
        if (!locale && s->hdr.argc > 0 && !JS_IsUndefined(s->hdr.argv[0])) {
            r = step_tostring_run(ctx, &s->hdr, s->hdr.argv[0], cb_result, &s->sep, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            if (is_ta) {
                /* ToString(separator) can DETACH or shrink the buffer, so the count is re-read after it and the
                   walk covers only what survived. s->oldlen still holds the count from before, and the tail
                   below emits the separators the lost elements would have contributed — which is exactly what a
                   resize is observable as. */
                int64_t newlen = JS_VALUE_GET_OBJ(s->obj)->u.array.count;
                if (newlen < s->len) s->len = newlen;
            }
        }
        s->i = 0;
        s->hdr.stage = 3;
    }

    for (;;) {
        if (s->hdr.stage == 3) {
            /* the loop HEAD is its own stage precisely because it writes to the buffer: the read below suspends
               and re-enters this function at its own stage, so a separator emitted in the same block as the read
               would be emitted again on every resume — which under forced preemption is every element. */
            if (s->i >= s->len)
                break;
            if (s->i > 0) {
                if (JS_IsUndefined(s->sep)) {
                    string_buffer_putc8(&s->b, ',');
                } else {
                    JSString *p = JS_VALUE_GET_STRING(s->sep);   /* re-derived: a C local would be gone */
                    string_buffer_concat(&s->b, p, 0, p->len);
                }
            }
            s->hdr.stage = 8;
        }
        if (s->hdr.stage == 8) {
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->i, cb_result, &s->el, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 4;
        }
        if (s->hdr.stage == 4) {
            if (JS_IsNull(s->el) || JS_IsUndefined(s->el)) {
                /* a hole or a nullish element contributes nothing but the separator */
                JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
                s->i++;
                s->hdr.stage = 3;
                continue;
            }
            s->hdr.stage = locale ? 5 : 7;
        }
        if (s->hdr.stage == 5) {
            r = step_getprop_run(ctx, &s->hdr, s->el, JS_ATOM_toLocaleString, cb_result, &s->cb[1],
                                 out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->cb[0] = s->el;                 /* the receiver: ownership moves into the call buffer */
            s->el = JS_UNDEFINED;
            s->hdr.stage = 6;
            *out_cb = s->cb; *out_argc = 0;
            return 3;                          /* a non-callable toLocaleString throws HERE, as Invoke does */
        }
        if (s->hdr.stage == 6) {
            s->el = cb_result; cb_result = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[0]); s->cb[0] = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[1]); s->cb[1] = JS_UNDEFINED;
            s->hdr.stage = 7;
        }
        DCHECK(s->hdr.stage == 7, "Array.prototype.join: unknown stage");
        r = step_tostring_run(ctx, &s->hdr, s->el, cb_result, &str, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
        if (string_buffer_concat_value_free(&s->b, str))
            return -1;
        s->i++;
        s->hdr.stage = 3;
    }

    JS_FreeValue(ctx, cb_result);
    if (is_ta) {
        /* the separators for the elements a resizing separator-coercion removed */
        for (s->i = s->len > 1 ? s->len : 1; s->i < s->oldlen; s->i++) {
            if (JS_IsUndefined(s->sep)) {
                string_buffer_putc8(&s->b, ',');
            } else {
                JSString *p = JS_VALUE_GET_STRING(s->sep);
                string_buffer_concat(&s->b, p, 0, p->len);
            }
        }
    }
    /* string_buffer_end NULLs the buffer on every path that consumed it and leaves it intact on the error
       path, so the teardown's string_buffer_free is right either way. */
    s->result = string_buffer_end(&s->b);
    return JS_IsException(s->result) ? -1 : 0;
}

static JSValue js_array_join_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayJoin *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    DCHECK(s->b.ctx != NULL, "the join buffer is initialised by stage 0's first statement, before any throw");
    string_buffer_free(&s->b);
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->sep);
    JS_FreeValue(ctx, s->el);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    js_free(ctx, s);
    return r;
}

/* Append to / pop from an ENGINE-PRIVATE array — JSON.stringify's cycle stack, the property-walk accumulators.
   The receiver is one this engine made and the page has never seen, so there is no accessor, no trap and no
   prototype lookup to reach: this is the same computation the builtins' fast-array span performs, with none of
   the observable steps that made them machines. It is NOT a fallback for those — nothing routes here. */
static int js_array_private_push(JSContext *ctx, JSValueConst arr, JSValueConst v)
{
    int64_t len;
    if (js_get_length64(ctx, &len, arr))
        return -1;
    return JS_SetPropertyInt64(ctx, arr, len, js_dup(v)) < 0 ? -1 : 0;
}

static int js_array_private_pop(JSContext *ctx, JSValueConst arr)
{
    int64_t len;
    if (js_get_length64(ctx, &len, arr))
        return -1;
    if (len <= 0)
        return 0;
    /* TRUNCATE, never DeletePropertyOrThrow: a delete takes a dense array out of its fast representation, and the
       next js_internal_array_includes on the same engine-owned array then hits its "must be a fast array" DFAIL.
       The builtin's own fast path decrements the element count for the same reason. */
    return JS_SetProperty(ctx, arr, JS_ATOM_length, js_int64(len - 1)) < 0 ? -1 : 0;
}

/* 23.1.3.22 pop / 23.1.3.26 shift — one machine, the shift flag in the declaration, exactly as the C body was
   one function with a magic. LengthOfArrayLike, the element Get, shift's element SHIFT, the Delete and the final
   Set(length) are all the page's code on an exotic receiver, and js_array_pop ran every one of them from C.
   The fast-array span stays: js_get_fast_array with count32 == len is the statement that the receiver is a plain
   dense array, so that branch has no observable step in it at all.
   Stages: 0 ToObject, 1 length, 2 the element Get, 3 the shift, 4 the Delete, 5 Set(O,"length",newLen). */

static int js_array_pop_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayPop *s = st;
    int shift = (s->hdr.arg != 0);
    JSValue *arrp;
    uint32_t count32;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->res = JS_UNDEFINED;
        s->len = 0; s->newLen = 0; s->cs_i = 0; s->present = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->newLen = 0;
        s->hdr.stage = 5;
        if (s->len > 0) {
            s->newLen = s->len - 1;
            if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == s->len) {
                JSObject *p = JS_VALUE_GET_OBJ(s->obj);
                if (shift) {
                    s->res = arrp[0];
                    memmove(arrp, arrp + 1, (count32 - 1) * sizeof(*arrp));
                } else {
                    s->res = arrp[count32 - 1];
                }
                p->u.array.count--;
            } else {
                s->hdr.stage = 2;
            }
        }
    }
    if (s->hdr.stage == 2) {
        r = step_getidx_run(ctx, &s->hdr, s->obj, shift ? 0 : s->newLen, cb_result, &s->res, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->cs_i = 0;
        s->hdr.stage = shift ? 3 : 4;
    }
    if (s->hdr.stage == 3) {   /* shift: everything above index 0 moves down one */
        r = step_copysub_run(ctx, &s->hdr, s->obj, 0, 1, s->len - 1, +1,
                             &s->cs_i, &s->present, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 4;
    }
    if (s->hdr.stage == 4) {
        r = step_delidx_run(ctx, &s->hdr, s->obj, s->newLen, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 5;
    }
    r = step_setprop_run(ctx, &s->hdr, s->obj, JS_ATOM_length, js_int64(s->newLen), cb_result, out_cb, out_argc);
    if (r) return r < 0 ? -1 : r;
    return 0;
}

static JSValue js_array_pop_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayPop *s = st;
    JSValue r = take_result ? s->res : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->res);
    JS_FreeValue(ctx, s->obj);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.23 push / 23.1.3.34 unshift — one machine, the unshift flag in the declaration. LengthOfArrayLike,
   unshift's element SHIFT, each inserted write and the final Set(length) are the page's code, and js_array_push
   ran them from C. The dense-array push fast path stays, guarded by everything that makes it unobservable
   (a plain fast Array with the standard prototype, a writable int `length` that matches the element count).
   Stages: 0 the fast path / ToObject, 1 length, 2 unshift's shift, 3 the inserted writes,
   4 Set(O,"length",newLen). */

static int js_array_push_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayPush *s = st;
    int unshift = (s->hdr.arg != 0);
    int i, r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->obj = JS_UNDEFINED;
        s->len = 0; s->newLen = 0; s->from = 0; s->cs_i = 0; s->i = 0; s->present = 0;
        /* the dense-array append: no accessor, no trap, no prototype lookup is reachable under these guards */
        if (likely(JS_VALUE_GET_TAG(s->hdr.this_val) == JS_TAG_OBJECT && !unshift)) {
            JSObject *p = JS_VALUE_GET_OBJ(s->hdr.this_val);
            if (likely(p->class_id == JS_CLASS_ARRAY &&
                       p->fast_array &&
                       p->extensible &&
                       p->shape->proto == JS_VALUE_GET_OBJ(ctx->class_proto[JS_CLASS_ARRAY]) &&
                       ctx->std_array_prototype)) {
                uint32_t array_len, new_len;
                if (likely(JS_VALUE_GET_TAG(p->prop[0].u.value) == JS_TAG_INT &&
                           (get_shape_prop(p->shape)->flags & JS_PROP_WRITABLE))) {
                    array_len = JS_VALUE_GET_INT(p->prop[0].u.value);
                    new_len = array_len + s->hdr.argc;
                    if (likely(array_len == p->u.array.count &&
                               new_len >= array_len && new_len <= (uint32_t)INT32_MAX)) {
                        if (unlikely(new_len > p->u.array.u1.size)) {
                            if (expand_fast_array(ctx, p, new_len))
                                return -1;
                        }
                        /* Forced-exec COW: this path writes values[] directly (bypassing
                           add_fast_array_element's capture), so record each created element slot so a shared
                           array's per-flow push is isolated (cow_unapply truncates it away). */
                        for (i = 0; i < s->hdr.argc; i++)
                            cow_capture_append(ctx, s->hdr.this_val, __JS_AtomFromUInt32(array_len + i));
                        for (i = 0; i < s->hdr.argc; i++)
                            p->u.array.u.values[array_len + i] = js_dup(s->hdr.argv[i]);
                        p->u.array.count = new_len;
                        p->prop[0].u.value = js_uint32(new_len);
                        s->newLen = new_len;
                        return 0;
                    }
                }
            }
        }
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->newLen = s->len + s->hdr.argc;
        if (s->newLen > MAX_SAFE_INTEGER) {
            JS_ThrowTypeError(ctx, "Array loo long");
            return -1;
        }
        s->from = s->len;
        s->cs_i = 0; s->i = 0;
        s->hdr.stage = (unshift && s->hdr.argc > 0) ? 2 : 3;
    }
    if (s->hdr.stage == 2) {   /* unshift: everything moves up by argc, backwards so the copy does not overlap */
        r = step_copysub_run(ctx, &s->hdr, s->obj, s->hdr.argc, 0, s->len, -1,
                             &s->cs_i, &s->present, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->from = 0;
        s->hdr.stage = 3;
    }
    while (s->hdr.stage == 3) {
        if (s->i >= s->hdr.argc) { JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED; s->hdr.stage = 4; break; }
        r = step_setidx_run(ctx, &s->hdr, s->obj, s->from + s->i, step_arg(&s->hdr, s->i),
                            cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->i++;
    }
    r = step_setprop_run(ctx, &s->hdr, s->obj, JS_ATOM_length, js_int64(s->newLen), cb_result, out_cb, out_argc);
    if (r) return r < 0 ? -1 : r;
    return 0;
}

static JSValue js_array_push_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayPush *s = st;
    JSValue r = take_result ? js_int64(s->newLen) : JS_UNDEFINED;
    JS_FreeValue(ctx, s->obj);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.25 Array.prototype.reverse. Every step of the swap is the page's code on an exotic receiver — the
   length read, both HasProperty asks, both Gets, and then two writes that are a Set or a
   DeletePropertyOrThrow depending on which side existed. js_array_reverse performed all of them from C.
   The DENSE span stays: js_get_fast_array with count32 == len is the statement that no accessor, no Proxy trap
   and no prototype lookup is reachable, so those slots swap with no observable step at all.
   Stages: 0 ToObject, 1 length + the dense span, 2 pair head, 3 Has(l), 4 Get(l), 5 Has(h), 6 Get(h),
   7 the first write, 8 the second. */

static int js_array_reverse_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayReverse *s = st;
    JSValue *arrp;
    uint32_t count32;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->lval = JS_UNDEFINED; s->hval = JS_UNDEFINED;
        s->len = 0; s->l = 0; s->h = 0; s->l_present = 0; s->h_present = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == s->len) {
            uint32_t ll, hh;
            if (count32 > 1) {
                for (ll = 0, hh = count32 - 1; ll < hh; ll++, hh--) {
                    JSValue t = arrp[ll];
                    arrp[ll] = arrp[hh];
                    arrp[hh] = t;
                }
            }
            return 0;
        }
        s->l = 0; s->h = s->len - 1;
        s->hdr.stage = 2;
    }
    for (;;) {
        if (s->hdr.stage == 2) {
            if (s->l >= s->h) { JS_FreeValue(ctx, cb_result); return 0; }
            s->hdr.stage = 3;
        }
        if (s->hdr.stage == 3) {
            r = step_hasidx_run(ctx, &s->hdr, s->obj, s->l, cb_result, &s->l_present, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = s->l_present ? 4 : 5;
        }
        if (s->hdr.stage == 4) {
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->l, cb_result, &s->lval, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 5;
        }
        if (s->hdr.stage == 5) {
            r = step_hasidx_run(ctx, &s->hdr, s->obj, s->h, cb_result, &s->h_present, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = s->h_present ? 6 : 7;
        }
        if (s->hdr.stage == 6) {
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->h, cb_result, &s->hval, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 7;
        }
        /* THE two writes. Which pair they are is decided by which side existed, and a HOLE on one side is a
           DeletePropertyOrThrow on the other — the spec's own three cases, in the spec's order. */
        if (s->hdr.stage == 7) {
            if (s->h_present)
                r = step_setidx_run(ctx, &s->hdr, s->obj, s->l, s->hval, cb_result, out_cb, out_argc);
            else if (s->l_present)
                r = step_delidx_run(ctx, &s->hdr, s->obj, s->l, cb_result, out_cb, out_argc);
            else
                { JS_FreeValue(ctx, cb_result); r = 0; }
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 8;
        }
        if (s->h_present && !s->l_present)
            r = step_delidx_run(ctx, &s->hdr, s->obj, s->h, cb_result, out_cb, out_argc);
        else if (s->l_present)
            r = step_setidx_run(ctx, &s->hdr, s->obj, s->h, s->lval, cb_result, out_cb, out_argc);
        else
            { JS_FreeValue(ctx, cb_result); r = 0; }
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        JS_FreeValue(ctx, s->lval); s->lval = JS_UNDEFINED;
        JS_FreeValue(ctx, s->hval); s->hval = JS_UNDEFINED;
        s->l++; s->h--;
        s->hdr.stage = 2;
    }
}

static JSValue js_array_reverse_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayReverse *s = st;
    JSValue r = take_result ? s->obj : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->lval);
    JS_FreeValue(ctx, s->hval);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.33 Array.prototype.toReversed — a.slice().reverse() with the twist that a.slice() leaves the holes of a
   sparse array intact whereas a.toReversed() replaces them with undefined, so the result is dense. It does not
   consult Array[@@species]; the result is always a base Array, which is why the writes into it are `!`
   CreateDataPropertyOrThrow on an engine-private object and reach no page code at all — only the READS do.
   Those reads are the page's: LengthOfArrayLike is a `length` getter or a Proxy `get` trap, and each element is
   step 5.c's `? Get(O, from)` on an accessor or a trap. js_array_toReversed performed all of them from C, so a
   loop in any of them had no flow base and aborted at its back-edge.
   It also asked HasProperty before every read (JS_TryGetPropertyInt64), which step 5.c does NOT: on
   `new Proxy([1,2],{has:()=>false, get:()=>'V'})` that fired two `has` traps and produced [undefined,undefined]
   where the spec yields ["V","V"]. The step sub-sequence is the plain Get the spec names.
   The FAST-ARRAY span stays: js_get_fast_array is precisely the statement that no accessor, no Proxy trap and no
   prototype lookup is reachable, so it is the same computation with no observable step.
   Stages: 0 ToObject, 1 length + allocate + the dense span, 2 the element read. */

static int js_array_toreversed_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayToReversed *s = st;
    JSValue *arrp;
    uint32_t count32;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->arr = JS_UNDEFINED; s->el = JS_UNDEFINED;
        s->len = 0; s->k = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        /* ArrayCreate(len) fills the storage with undefined, so a suspension part-way through the walk leaves a
           GC-walkable array — the slots the page has not reached yet are already holes-as-undefined. */
        s->arr = js_allocate_fast_array(ctx, s->len);
        if (JS_IsException(s->arr)) { s->arr = JS_UNDEFINED; return -1; }
        if (s->len <= 0) return 0;
        if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == s->len) {
            JSValue *pval = JS_VALUE_GET_OBJ(s->arr)->u.array.u.values;
            int64_t i;
            for (i = s->len - 1; i >= 0; i--, pval++)
                *pval = js_dup(arrp[i]);
            return 0;
        }
        s->hdr.stage = 2;
    }
    for (;;) {
        if (s->k >= s->len) { JS_FreeValue(ctx, cb_result); return 0; }
        /* step 5.c: `? Get(O, ! ToString(𝔽(len - k - 1)))` — descending, and the order is observable. */
        r = step_getidx_run(ctx, &s->hdr, s->obj, s->len - 1 - s->k, cb_result, &s->el, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        /* step 5.d: `!` CreateDataPropertyOrThrow(A, Pk, fromValue). */
        arr_dense_put(ctx, s->arr, s->k, s->el);
        s->el = JS_UNDEFINED;
        s->k++;
    }
}

static JSValue js_array_toreversed_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayToReversed *s = st;
    JSValue r = take_result ? s->arr : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->arr);
    JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->el);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.28 slice / 23.1.3.31 splice — ONE machine, `splice` in hdr.arg, exactly as the C function was one body
   with a magic. Everything observable is the page's code: LengthOfArrayLike, both index coercions (a `valueOf`
   runs there), ArraySpeciesCreate's Get(constructor) / Get(@@species) / Construct, every HasProperty and Get of
   the copied range, Set(A,"length",n), and splice's own deletes, writes and final Set(O,"length"). js_array_slice
   performed all of it from C, so a loop in any of them had no flow base and aborted at its back-edge.
   The FAST-ARRAY paths stay: js_get_fast_array / js_is_fast_array is precisely the statement that no accessor, no
   Proxy trap and no prototype lookup is reachable, so they are the same computation with no observable step — not
   a second implementation of one.
   Stages: 0 ToObject, 1 length, 2 start, 3 the second index, 4 ArraySpeciesCreate, 5 copy head, 6 HasProperty,
   7 Get, 14 the element define, 8 Set(A,"length",n), 9 splice's tail head, 13 the element shift, 10 delete,
   11 the inserted items, 12 Set(O,"length",newLen). (13 and 14 are out of order because they were added after
   the rest; a stage is a wire value in a suspended state, and renumbering to tidy the list would silently
   repoint anything parked at the old one.) */

static int js_array_slice_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArraySlice *s = st;
    int splice = (s->hdr.arg != 0);
    JSValue *arrp;
    uint32_t count32;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->arr = JS_UNDEFINED; s->el = JS_UNDEFINED;
        s->len = 0; s->start = 0; s->count = 0; s->del_count = 0; s->final = 0;
        s->k = 0; s->n = 0; s->new_len = 0; s->di = 0; s->cs_i = 0;
        s->item_count = 0; s->ii = 0; s->present = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->start, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->start = arr_clamp_idx(s->start, s->len);
        s->hdr.stage = 3;
    }
    if (s->hdr.stage == 3) {
        if (splice) {
            if (s->hdr.argc == 0) {
                s->item_count = 0; s->del_count = 0;
            } else if (s->hdr.argc == 1) {
                s->item_count = 0; s->del_count = s->len - s->start;
            } else {
                s->item_count = s->hdr.argc - 2;
                r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 1), cb_result, &s->del_count,
                                     out_cb, out_argc);
                cb_result = JS_UNDEFINED;
                if (r) return r < 0 ? -1 : r;
                /* JS_ToInt64Clamp(…, 0, len - start, 0): no negative-relative offset here */
                if (s->del_count < 0) s->del_count = 0;
                else if (s->del_count > s->len - s->start) s->del_count = s->len - s->start;
            }
            if (s->len + s->item_count - s->del_count > MAX_SAFE_INTEGER) {
                JS_ThrowTypeError(ctx, "Array loo long");
                return -1;
            }
            s->count = s->del_count;
        } else {
            s->final = s->len;
            if (!JS_IsUndefined(step_arg(&s->hdr, 1))) {
                r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 1), cb_result, &s->final,
                                     out_cb, out_argc);
                cb_result = JS_UNDEFINED;
                if (r) return r < 0 ? -1 : r;
                s->final = arr_clamp_idx(s->final, s->len);
            }
            s->count = max_int64(s->final - s->start, 0);
        }
        s->hdr.stage = 4;
    }
    if (s->hdr.stage == 4) {
        r = step_species_run(ctx, &s->hdr, s->obj, cb_result, js_int64(s->count), &s->arr, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->k = s->start;
        s->final = s->start + s->count;
        s->n = 0;
        s->hdr.stage = 5;
    }
    if (s->hdr.stage == 5) {
        /* The fast-array test on `arr` is what makes JS_CreateDataPropertyUint32Const unable to touch `obj`:
           neither side can run a trap, so this whole span has no observable step in it. */
        if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && js_is_fast_array(ctx, s->arr)) {
            for (; s->k < s->final && s->k < count32; s->k++, s->n++) {
                if (JS_CreateDataPropertyUint32Const(ctx, s->arr, s->n, arrp[s->k], JS_PROP_THROW) < 0)
                    return -1;
            }
        }
        s->hdr.stage = 6;
    }
    /* GUARDED on the two stages this walk owns: a resume lands at the top of the machine, and an unguarded loop
       here would run the element Get for a flow that had suspended in the splice tail. */
    while (s->hdr.stage == 6 || s->hdr.stage == 7 || s->hdr.stage == 14) {
        if (s->hdr.stage == 6) {
            if (s->k >= s->final) { JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED; s->hdr.stage = 8; break; }
            r = step_hasidx_run(ctx, &s->hdr, s->obj, s->k, cb_result, &s->present, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            if (!s->present) { s->k++; s->n++; continue; }   /* a HOLE stays a hole in the result */
            s->hdr.stage = 7;
        }
        if (s->hdr.stage == 7) {
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->k, cb_result, &s->el, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 14;
        }
        r = step_defidx_run(ctx, &s->hdr, s->arr, s->n, s->el, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;   /* the define BORROWS it */
        s->k++; s->n++;
        s->hdr.stage = 6;
    }
    if (s->hdr.stage == 8) {
        r = step_setprop_run(ctx, &s->hdr, s->arr, JS_ATOM_length, js_int64(s->n), cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        if (!splice) return 0;
        s->hdr.stage = 9;
    }
    if (s->hdr.stage == 9) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->new_len = s->len + s->item_count - s->del_count;
        s->cs_i = 0;
        s->hdr.stage = (s->item_count != s->del_count) ? 13 : 10;
        if (s->hdr.stage == 10)
            s->di = s->new_len;   /* nothing to shift and nothing to trim */
    }
    if (s->hdr.stage == 13) {   /* the element SHIFT: every read and write in it is the page's */
        r = step_copysub_run(ctx, &s->hdr, s->obj, s->start + s->item_count,
                             s->start + s->del_count, s->len - (s->start + s->del_count),
                             s->item_count <= s->del_count ? +1 : -1,
                             &s->cs_i, &s->present, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->di = s->len;
        s->hdr.stage = 10;
    }
    while (s->hdr.stage == 10) {
        if (s->di <= s->new_len) { JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED; s->ii = 0; s->hdr.stage = 11; break; }
        r = step_delidx_run(ctx, &s->hdr, s->obj, s->di - 1, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->di--;
    }
    while (s->hdr.stage == 11) {
        if (s->ii >= s->item_count) { JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED; s->hdr.stage = 12; break; }
        r = step_setidx_run(ctx, &s->hdr, s->obj, s->start + s->ii, step_arg(&s->hdr, s->ii + 2),
                            cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->ii++;
    }
    r = step_setprop_run(ctx, &s->hdr, s->obj, JS_ATOM_length, js_int64(s->new_len), cb_result,
                         out_cb, out_argc);
    if (r) return r < 0 ? -1 : r;
    return 0;
}

static JSValue js_array_slice_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArraySlice *s = st;
    JSValue r = take_result ? s->arr : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->arr);
    JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->el);
    js_free(ctx, s);
    return r;
}

/* 23.1.3.35 Array.prototype.toSpliced — splice without mutating the receiver. It does not consult
   Array[@@species]; the result is always a dense base Array, so every write into it is a `!`
   CreateDataPropertyOrThrow on an engine-private object and reaches no page code. The READS are the page's:
   LengthOfArrayLike, ToIntegerOrInfinity of `start` and of `skipCount` (a `valueOf` runs there), and steps 14.b
   and 16.c's `? Get(O, Pi)` for every copied element. js_array_toSpliced ran all of them from C, so a loop in
   any of them had no flow base and aborted at its back-edge.
   It also asked HasProperty before every read (JS_TryGetPropertyInt64), which 14.b and 16.c do NOT: on a Proxy
   whose `has` says false and whose `get` returns a value, that produced undefined where the spec yields the
   value. The step sub-sequence is the plain Get the spec names.
   The FAST-ARRAY span stays: js_get_fast_array is precisely the statement that no accessor, no Proxy trap and no
   prototype lookup is reachable, so it is the same computation with no observable step.
   Stages: 0 ToObject, 1 length, 2 start, 3 skipCount + allocate + the dense span, 4 the head reads,
   5 the inserted items, 6 the tail reads. */

static int js_array_tospliced_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayToSpliced *s = st;
    JSValue *arrp;
    uint32_t count32;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->arr = JS_UNDEFINED; s->el = JS_UNDEFINED;
        s->len = 0; s->start = 0; s->del = 0; s->newlen = 0; s->i = 0; s->from = 0; s->add = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        /* steps 3-4: ToIntegerOrInfinity(start), then the negative-relative clamp into [0, len]. */
        r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->start, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->start = arr_clamp_idx(s->start, s->len);
        s->hdr.stage = 3;
    }
    if (s->hdr.stage == 3) {
        /* steps 6-8: `start` absent skips nothing, `skipCount` absent skips the whole tail, and only the
           present-and-given case coerces — which is why this reads argc and not the padded operand. */
        if (s->hdr.argc == 0) {
            s->del = 0;
        } else if (s->hdr.argc == 1) {
            s->del = s->len - s->start;
        } else {
            r = step_toint64_run(ctx, &s->hdr, step_arg(&s->hdr, 1), cb_result, &s->del, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            if (s->del < 0) s->del = 0;
            else if (s->del > s->len - s->start) s->del = s->len - s->start;
        }
        s->add = s->hdr.argc > 2 ? s->hdr.argc - 2 : 0;
        s->newlen = s->len + s->add - s->del;
        if (s->newlen > MAX_SAFE_INTEGER) {
            JS_ThrowTypeError(ctx, "invalid array length");
            return -1;
        }
        s->arr = js_allocate_fast_array(ctx, s->newlen);
        if (JS_IsException(s->arr)) { s->arr = JS_UNDEFINED; return -1; }
        if (s->newlen <= 0) return 0;
        /* the coercions above are page code and may have reshaped the receiver, so the fast-array test is made
           here and not before them. */
        if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == s->len) {
            int64_t i, j, w = 0;
            for (i = 0; i < s->start; i++)
                arr_dense_put(ctx, s->arr, w++, js_dup(arrp[i]));
            for (j = 0; j < s->add; j++)
                arr_dense_put(ctx, s->arr, w++, js_dup(step_arg(&s->hdr, (int)(2 + j))));
            for (i += s->del; i < s->len; i++)
                arr_dense_put(ctx, s->arr, w++, js_dup(arrp[i]));
            DCHECK(w == s->newlen, "the dense toSpliced copy did not fill its allocated result exactly");
            return 0;
        }
        s->i = 0;
        s->from = s->start + s->del;
        s->hdr.stage = 4;
    }
    /* step 14: the head, `? Get(O, Pi)` for i < actualStart. */
    while (s->hdr.stage == 4) {
        if (s->i >= s->start) { s->hdr.stage = 5; break; }
        r = step_getidx_run(ctx, &s->hdr, s->obj, s->i, cb_result, &s->el, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        arr_dense_put(ctx, s->arr, s->i, s->el);
        s->el = JS_UNDEFINED;
        s->i++;
    }
    if (s->hdr.stage == 5) {
        /* step 15: the inserted items, which are already values — nothing observable happens here. */
        int64_t j;
        for (j = 0; j < s->add; j++, s->i++)
            arr_dense_put(ctx, s->arr, s->i, js_dup(step_arg(&s->hdr, (int)(2 + j))));
        s->hdr.stage = 6;
    }
    /* step 16: the tail, `? Get(O, from)` written at Pi — two cursors, because the copy is a shift. */
    for (;;) {
        if (s->i >= s->newlen) {
            JS_FreeValue(ctx, cb_result);
            DCHECK(s->from == s->len, "the toSpliced tail walk did not consume the receiver exactly");
            return 0;
        }
        r = step_getidx_run(ctx, &s->hdr, s->obj, s->from, cb_result, &s->el, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        arr_dense_put(ctx, s->arr, s->i, s->el);
        s->el = JS_UNDEFINED;
        s->i++;
        s->from++;
    }
}

static JSValue js_array_tospliced_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayToSpliced *s = st;
    JSValue r = take_result ? s->arr : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->arr);
    JS_FreeValue(ctx, s->obj);
    JS_FreeValue(ctx, s->el);
    js_free(ctx, s);
    return r;
}


/* ---- Array.from over an array-like as a step machine (see JSArrayFromLike) ---- */
static int js_array_fromlike_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayFromLike *s = st;
    int mapping;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->items = JS_UNDEFINED; s->arr = JS_UNDEFINED; s->el = JS_UNDEFINED;
        s->len = 0; s->k = 0;
        s->items = JS_ToObject(ctx, step_arg(&s->hdr, 0));
        if (JS_IsException(s->items)) { s->items = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    mapping = !JS_IsUndefined(step_arg(&s->hdr, 1));
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->items, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        /* step 7: Construct(C, «len») when the receiver is a constructor — `Array.from.call(Sub, arrayLike)` makes
           that user code — else ArrayCreate(len), which invokes nothing. */
        if (JS_IsConstructor(ctx, s->hdr.this_val)) {
            s->cb[0] = s->hdr.this_val;   /* borrowed: the header owns the receiver */
            s->cb[1] = js_int64(s->len);
            *out_cb = s->cb; *out_argc = 1;
            s->hdr.stage = 3;
            return 4;
        }
        {
            JSValue len_val = js_int64(s->len);
            s->arr = js_array_constructor(ctx, JS_UNDEFINED, 1, vc(&len_val));
            JS_FreeValue(ctx, len_val);
            if (JS_IsException(s->arr)) { s->arr = JS_UNDEFINED; return -1; }
        }
        s->hdr.stage = 4;
    }
    if (s->hdr.stage == 3) {
        s->arr = cb_result;   /* the constructed object */
        cb_result = JS_UNDEFINED;
        s->hdr.stage = 4;
    }
    for (;;) {
        /* the loop is left at stage 7 (the trailing length write), and that write SUSPENDS — so a re-entry lands
           here with a stage no arm below matches. Without this the loop spun forever on the resume. */
        if (s->hdr.stage == 7) break;
        if (s->hdr.stage == 4) {
            if (s->k >= s->len) { s->hdr.stage = 7; break; }
            s->hdr.stage = 5;
        }
        if (s->hdr.stage == 5) {
            r = step_getidx_run(ctx, &s->hdr, s->items, s->k, cb_result, &s->el, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 6;
        }
        if (s->hdr.stage == 6) {
            if (mapping) {
                /* Call(mapfn, thisArg, «kValue, 𝔽(k)»). Every slot is a BORROWED view of something this state or
                   its header owns, so the request buffer has nothing to release. */
                s->cb[0] = (JSValue)step_arg(&s->hdr, 2);   /* thisArg */
                s->cb[1] = (JSValue)step_arg(&s->hdr, 1);   /* the mapper */
                s->cb[2] = s->el;
                s->cb[3] = js_int64(s->k);
                *out_cb = s->cb; *out_argc = 2;
                s->hdr.stage = 8;
                return 3;
            }
            s->hdr.stage = 9;
        }
        if (s->hdr.stage == 8) {
            JS_FreeValue(ctx, s->el);
            s->el = cb_result;   /* the mapped value REPLACES the element */
            cb_result = JS_UNDEFINED;
            s->hdr.stage = 9;
        }
        if (s->hdr.stage == 9) {
            /* 23.1.2.1 step 8.f CreateDataPropertyOrThrow(A, Pk, mappedValue): A is Construct(C, len) when `this`
               is a constructor, so on a Proxy or subclass this is the page's `defineProperty` trap. The element is
               BORROWED across the write and freed once it lands. */
            r = step_defidx_run(ctx, &s->hdr, s->arr, s->k, s->el, cb_result, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
            s->k++;
            s->hdr.stage = 4;
        }
    }
    /* step 10: Set(A, "length", 𝔽(len), true). On a plain Array this is the internal length; on a SUBCLASS with a
       `length` setter it is user code, which is why it goes through the keyed-WRITE step like every other write. */
    DCHECK(s->hdr.stage == 7, "the array-like walk left its loop in an unexpected stage");
    /* the length value is parked on the state, not a C local: the write can suspend and this function's locals do
       not survive that — the request BORROWS what it is handed. */
    if (JS_IsUndefined(s->el)) s->el = js_int64(s->len);
    r = step_setprop_run(ctx, &s->hdr, s->arr, JS_ATOM_length, s->el, cb_result, out_cb, out_argc);
    cb_result = JS_UNDEFINED;
    if (r) return r < 0 ? -1 : r;
    JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
    return 0;
}

static JSValue js_array_fromlike_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayFromLike *s = st;
    JSValue r = take_result ? s->arr : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->arr);
    JS_FreeValue(ctx, s->el);
    JS_FreeValue(ctx, s->items);
    js_free(ctx, s);
    return r;
}

/* ---- Array.prototype.flat / flatMap as a step machine (see JSArrayFlat) ---- */
static int js_flat_push(JSContext *ctx, JSArrayFlat *s, JSValue source, int64_t len, int depth)
{
    JSFlatFrame *f;
    if (s->sp >= s->cap) {
        int nc = s->cap ? s->cap * 2 : 8;
        JSFlatFrame *ns = js_realloc(ctx, s->fr, (size_t)nc * sizeof(JSFlatFrame));
        if (!ns) { JS_FreeValue(ctx, source); return -1; }
        s->fr = ns; s->cap = nc;
    }
    f = &s->fr[s->sp++];
    f->source = source;   /* owned, transferred */
    f->len = len; f->i = 0; f->depth = depth;
    return 0;
}

static int js_array_flat_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayFlat *s = st;
    int is_map = (s->hdr.arg == ARRAYFLAT_FLATMAP);
    JSFlatFrame *f;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->arr = JS_UNDEFINED; s->el = JS_UNDEFINED;
        s->fr = NULL; s->sp = 0; s->cap = 0;
        s->target_index = 0; s->len0 = 0; s->depth0 = 1; s->present = 0;
        s->obj = JS_ToObject(ctx, s->hdr.this_val);
        if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len0, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        /* flatMap validates its mapper BEFORE anything else observable; flat coerces its depth, which is where a
           `valueOf` gets to run. */
        if (is_map) {
            if (check_function(ctx, step_arg(&s->hdr, 0))) { JS_FreeValue(ctx, cb_result); return -1; }
        } else if (s->hdr.argc > 0 && !JS_IsUndefined(step_arg(&s->hdr, 0))) {
            r = step_toint32sat_run(ctx, &s->hdr, step_arg(&s->hdr, 0), cb_result, &s->depth0,
                                    out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
        }
        s->hdr.stage = 3;
    }
    if (s->hdr.stage == 3) {
        /* ArraySpeciesCreate(O, 0): a @@species getter and a subclass constructor are both user code, which
           step_species_run drives. */
        r = step_species_run(ctx, &s->hdr, s->obj, cb_result, js_int32(0), &s->arr, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        if (js_flat_push(ctx, s, js_dup(s->obj), s->len0, s->depth0) < 0) return -1;
        s->hdr.stage = 4;
    }
    for (;;) {
        if (s->hdr.stage == 4) {   /* frame head */
            if (s->sp == 0) { JS_FreeValue(ctx, cb_result); return 0; }   /* DONE: fini hands back s->arr */
            f = &s->fr[s->sp - 1];
            if (f->i >= f->len) {
                JS_FreeValue(ctx, f->source);
                s->sp--;
                continue;   /* the parent's cursor was advanced BEFORE it descended, so it just re-heads */
            }
            s->hdr.stage = 5;
        }
        f = &s->fr[s->sp - 1];
        if (s->hdr.stage == 5) {
            r = step_hasidx_run(ctx, &s->hdr, f->source, f->i, cb_result, &s->present, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 6;
        }
        if (s->hdr.stage == 6) {
            if (!s->present) { f->i++; s->hdr.stage = 4; continue; }   /* a HOLE is skipped, not flattened */
            s->hdr.stage = 7;
        }
        if (s->hdr.stage == 7) {
            r = step_getidx_run(ctx, &s->hdr, f->source, f->i, cb_result, &s->el, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->hdr.stage = 8;
        }
        if (s->hdr.stage == 8) {
            if (is_map && s->sp == 1) {
                /* Call(mapperFunction, thisArg, «element, 𝔽(sourceIndex), source»). Every slot is a BORROWED view
                   of something this state owns, so the request buffer has nothing to release. */
                s->cb[0] = (JSValue)step_arg(&s->hdr, 1);   /* thisArg */
                s->cb[1] = (JSValue)step_arg(&s->hdr, 0);   /* the mapper */
                s->cb[2] = s->el;
                s->cb[3] = js_int64(f->i);
                s->cb[4] = f->source;
                *out_cb = s->cb; *out_argc = 3;
                s->hdr.stage = 9;
                return 3;
            }
            s->hdr.stage = 10;
        }
        if (s->hdr.stage == 9) {
            JS_FreeValue(ctx, s->el);
            s->el = cb_result;   /* the mapped value REPLACES the element */
            cb_result = JS_UNDEFINED;
            s->hdr.stage = 10;
        }
        if (s->hdr.stage == 10) {
            if (f->depth > 0) {
                int ia = js_is_array(ctx, s->el);
                if (ia < 0) { JS_FreeValue(ctx, cb_result); return -1; }
                if (ia) { s->hdr.stage = 11; goto descend; }
            }
            if (s->target_index >= MAX_SAFE_INTEGER) {
                JS_FreeValue(ctx, cb_result);
                JS_ThrowTypeError(ctx, "Array too long");
                return -1;
            }
            s->hdr.stage = 12;
        }
        if (s->hdr.stage == 12) {
            /* 23.1.3.13.1 step 2.d.iii.4 CreateDataPropertyOrThrow(target, targetIndex, element): the target is
               ArraySpeciesCreate's, so on a Proxy or subclass this is the page's `defineProperty` trap. */
            r = step_defidx_run(ctx, &s->hdr, s->arr, s->target_index, s->el, cb_result, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
            s->target_index++;
            f->i++;
            s->hdr.stage = 4;
            continue;
        }
    descend:
        if (s->hdr.stage == 11) {
            int64_t sublen;
            r = step_length_run(ctx, &s->hdr, s->el, cb_result, &sublen, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            /* advance the PARENT before descending: when the child frame pops, the parent re-heads at the next
               index, which is what the C version's `continue` past the recursive call did. */
            f->i++;
            {
                JSValue sub = s->el;
                s->el = JS_UNDEFINED;
                if (js_flat_push(ctx, s, sub, sublen, f->depth - 1) < 0) return -1;
            }
            s->hdr.stage = 4;
        }
    }
}

static JSValue js_array_flat_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayFlat *s = st;
    JSValue r = take_result ? s->arr : JS_UNDEFINED;
    int i;
    if (!take_result) JS_FreeValue(ctx, s->arr);
    JS_FreeValue(ctx, s->el);
    JS_FreeValue(ctx, s->obj);
    for (i = 0; i < s->sp; i++) JS_FreeValue(ctx, s->fr[i].source);
    js_free(ctx, s->fr);
    js_free(ctx, s);
    return r;
}
/* Array sort */

typedef struct ValueSlot {
    JSValue val;
    JSString *str;
    int64_t pos;
} ValueSlot;

struct array_sort_context {
    JSContext *ctx;
    int exception;
    int has_method;
    JSValueConst method;
};

static int js_array_cmp_generic(const void *a, const void *b, void *opaque) {
    struct array_sort_context *psc = opaque;
    JSContext *ctx = psc->ctx;
    JSValueConst argv[2];
    JSValue res;
    ValueSlot *ap = (ValueSlot *)(void *)a;
    ValueSlot *bp = (ValueSlot *)(void *)b;
    int cmp;

    if (psc->exception)
        return 0;

    if (psc->has_method) {
        /* custom sort function is specified as returning 0 for identical
         * objects: avoid method call overhead.
         */
        if (!memcmp(&ap->val, &bp->val, sizeof(ap->val)))
            goto cmp_same;
        argv[0] = ap->val;
        argv[1] = bp->val;
        res = JS_Call(ctx, psc->method, JS_UNDEFINED, 2, argv);
        if (JS_IsException(res))
            goto exception;
        if (JS_VALUE_GET_TAG(res) == JS_TAG_INT) {
            int val = JS_VALUE_GET_INT(res);
            cmp = (val > 0) - (val < 0);
        } else {
            double val;
            if (JS_ToFloat64Free(ctx, &val, res) < 0)
                goto exception;
            cmp = (val > 0) - (val < 0);
        }
    } else {
        /* Not supposed to bypass ToString even for identical objects as
         * tested in test262/test/built-ins/Array/prototype/sort/bug_596_1.js
         */
        if (!ap->str) {
            JSValue str = JS_ToString(ctx, ap->val);
            if (JS_IsException(str))
                goto exception;
            ap->str = JS_VALUE_GET_STRING(str);
        }
        if (!bp->str) {
            JSValue str = JS_ToString(ctx, bp->val);
            if (JS_IsException(str))
                goto exception;
            bp->str = JS_VALUE_GET_STRING(str);
        }
        cmp = js_string_compare(ap->str, bp->str);
    }
    if (cmp != 0)
        return cmp;
cmp_same:
    /* make sort stable: compare array offsets */
    return (ap->pos > bp->pos) - (ap->pos < bp->pos);

exception:
    psc->exception = 1;
    return 0;
}

/* read the present, non-undefined elements into s->array (undefined -> the end, holes -> after that), alloc tmp,
   set up the first merge block. Returns 0 ok / -1 exception (safe to tear down). */
/* The receiver half. `method` is hdr.argv[0] — owned by the header for the machine's whole life, which is why
   the state can borrow it. */
static int js_array_sort_recv(JSContext *ctx, JSArraySort *s)
{
    int64_t i;
    s->obj = JS_UNDEFINED; s->method = step_arg(&s->hdr, 0); s->array = NULL; s->tmp = NULL;
    s->n = 0; s->len = 0; s->undefined_count = 0; s->pending = 0;
    s->width = 1; s->i = 0; s->lo = s->mid = s->hi = s->l = s->r = s->k = 0; s->wb = 0;
    s->coerced = JS_UNDEFINED; s->copy = JS_UNDEFINED; s->el = JS_UNDEFINED; s->cmpres = JS_UNDEFINED;
    for (i = 0; i < 4; i++) s->cb_args[i] = JS_UNDEFINED;
    s->obj = JS_ToObject(ctx, s->hdr.this_val);
    if (JS_IsException(s->obj)) { s->obj = JS_UNDEFINED; return -1; }
    return 0;
}

/* Collect the present, non-undefined elements into the merge array. Runs after the length, so it is its own
   function rather than the tail of an init. */
/* Gather the present, non-undefined elements. The ask and the read are each the page's code — an index accessor
   or a Proxy trap — and JS_TryGetPropertyInt64 reached both from C, so a loop in either preempted with no flow
   base before a single comparison had happened. s->n IS the write cursor, which is what makes an abandon
   mid-collect free exactly what was gathered. */
static int js_array_sort_collect(JSContext *ctx, JSArraySort *s, JSValue in, JSValue **out_cb, int *out_argc)
{
    int r;
    while (s->col_i < s->len) {
        if (s->elem_ph == 0) {
            r = step_hasidx_run(ctx, &s->hdr, s->obj, s->col_i, in, &s->present, out_cb, out_argc);
            in = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->elem_ph = 1;
        }
        if (!s->present) { s->col_i++; s->elem_ph = 0; continue; }
        {
            JSValue v;
            r = step_getidx_run(ctx, &s->hdr, s->obj, s->col_i, in, &v, out_cb, out_argc);
            in = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            s->elem_ph = 0;
            if (JS_IsUndefined(v)) {
                s->undefined_count++;
            } else {
                s->array[s->n].val = v; s->array[s->n].str = NULL; s->array[s->n].pos = s->col_i; s->n++;
            }
            s->col_i++;
        }
    }
    JS_FreeValue(ctx, in);
    if (s->n > 1) {
        s->tmp = js_malloc(ctx, (size_t)s->n * sizeof(ValueSlot));
        if (!s->tmp) return -1;
        s->lo = 0; s->mid = 1 < s->n ? 1 : s->n; s->hi = 2 < s->n ? 2 : s->n;   /* first block, width=1 */
        s->l = 0; s->r = s->mid; s->k = 0;
    }
    return 0;
}

/* Drive the merge until the next comparison is needed (return 1, out_args = the two element values) or the sort
   is complete (return 0). `res` (owned) is the comparator's return value for the pending comparison, or JS_UNDEFINED
   on the first call. Returns -1 on exception. */
static int js_array_sort_step(JSContext *ctx, JSArraySort *s, JSValue res, JSValueConst out_args[2],
                              JSValue **out_cb, int *out_argc)
{
    int rc;
    if (s->pending) {
        double v;
        /* SortCompare step 3.a coerces what the comparator RETURNED, and JS_ToFloat64Free did that from C — so
           a comparator returning an object ran its valueOf in an activation with no flow base, in the one
           machine that had already been built to park everything else. The result is held on the state because
           the coercion suspends. */
        if (s->hdr.num_phase == NUM_PH_START) {
            DCHECK(JS_IsUndefined(s->cmpres), "a comparator result is already being coerced on this sort");
            s->cmpres = res;
            res = JS_UNDEFINED;
        }
        rc = step_tofloat64_run(ctx, &s->hdr, s->cmpres, res, &v, out_cb, out_argc);
        res = JS_UNDEFINED;
        if (rc) return rc < 0 ? -1 : rc;
        JS_FreeValue(ctx, s->cmpres); s->cmpres = JS_UNDEFINED;
        s->pending = 0;
        /* step 3.b: a NaN v is +0, which a stable sort keeps in original order. `v <= 0` is FALSE for NaN, so
           every comparison took the right element and `[1,2,3,4].sort(() => NaN)` came out reversed. Asking
           whether v is GREATER than zero is the one form that answers both cases: NaN and 0 alike keep the
           left (earlier) element, which is what stability means. */
        if (!(v > 0)) s->tmp[s->k++] = s->array[s->l++];
        else          s->tmp[s->k++] = s->array[s->r++];
    } else if (s->hdr.str_phase == STR_PH_START) {
        JS_FreeValue(ctx, res);   /* JS_UNDEFINED on the first call, or a stray value */
        res = JS_UNDEFINED;
    }
    /* otherwise `res` is the primitive a default-ordering ToString is waiting for; the loop hands it back to
       the sub-sequence that asked, which is the only thing allowed to consume it. */
    for (;;) {
        if (s->width >= s->n) break;                 /* fully sorted (n<=1 lands here immediately) */
        if (s->i >= s->n) {                          /* this width pass done -> next width */
            s->width *= 2; s->i = 0;
            if (s->width >= s->n) break;
            s->lo = 0; s->mid = s->width < s->n ? s->width : s->n;
            s->hi = 2 * s->width < s->n ? 2 * s->width : s->n;
            s->l = 0; s->r = s->mid; s->k = 0;
            continue;
        }
        /* merge invariants — an active block [lo,hi) with ordered cursors, and the exactly-conserved output
           count (each element placed into tmp is consumed from exactly one run). A violation is a state-machine
           bug; crash at its origin (offensive programming) rather than silently mis-sorting. */
        assert(s->lo <= s->l && s->l <= s->mid && s->mid <= s->r && s->r <= s->hi && s->hi <= s->n);
        assert(s->k - s->lo == (s->l - s->lo) + (s->r - s->mid));
        if (s->l < s->mid && s->r < s->hi) {
            if (JS_IsUndefined(s->method)) {
                /* DEFAULT ordering: ToString both and compare. It lives HERE so ONE machine covers both
                   comparator kinds; leaving it in a second C body is the seam every bug this session came from.
                   Its two ToStrings ARE suspension points — an element with a user toString/valueOf runs the
                   page's code, and doing it with JS_ToString from here drove that to completion while the
                   comparator branch beside it parked correctly. ToString is not bypassed for identical values
                   (test262 Array/prototype/sort/bug_596_1.js), and ties fall back to original position for
                   stability. The cursors s->l and s->r do not move across a suspension, so the two slots this
                   re-derives on re-entry are the same two. */
                ValueSlot *ap = &s->array[s->l], *bp = &s->array[s->r];
                int cmp;
                if (s->cmp_ph == 0) {
                    if (!ap->str) {
                        rc = step_tostring_run(ctx, &s->hdr, ap->val, res, &s->coerced, out_cb, out_argc);
                        res = JS_UNDEFINED;
                        if (rc) return rc < 0 ? -1 : rc;
                        ap->str = JS_VALUE_GET_STRING(s->coerced);
                        s->coerced = JS_UNDEFINED;
                    }
                    s->cmp_ph = 1;
                }
                if (!bp->str) {
                    rc = step_tostring_run(ctx, &s->hdr, bp->val, res, &s->coerced, out_cb, out_argc);
                    res = JS_UNDEFINED;
                    if (rc) return rc < 0 ? -1 : rc;
                    bp->str = JS_VALUE_GET_STRING(s->coerced);
                    s->coerced = JS_UNDEFINED;
                }
                s->cmp_ph = 0;
                cmp = js_string_compare(ap->str, bp->str);
                if (cmp == 0)
                    cmp = (ap->pos > bp->pos) - (ap->pos < bp->pos);
                if (cmp <= 0) s->tmp[s->k++] = s->array[s->l++];
                else          s->tmp[s->k++] = s->array[s->r++];
                continue;
            }
            out_args[0] = s->array[s->l].val;   /* the ONE suspension point (a comparator was supplied) */
            out_args[1] = s->array[s->r].val;
            s->pending = 1;
            return 1;
        }
        while (s->l < s->mid) s->tmp[s->k++] = s->array[s->l++];   /* drain remainders */
        while (s->r < s->hi)  s->tmp[s->k++] = s->array[s->r++];
        { int64_t t; for (t = s->lo; t < s->hi; t++) s->array[t] = s->tmp[t]; }   /* copy block back */
        s->i += 2 * s->width;                        /* next block at this width */
        if (s->i < s->n) {
            s->lo = s->i; s->mid = s->i + s->width < s->n ? s->i + s->width : s->n;
            s->hi = s->i + 2 * s->width < s->n ? s->i + 2 * s->width : s->n;
            s->l = s->lo; s->r = s->mid; s->k = s->lo;
        }
    }
    return 0;   /* the merge is done: js_array_sort_vstep writes the sorted list back */
}

/* Release one gathered slot: the element and the ToString the default ordering cached on it. The writeback
   calls this as each slot lands, and the teardown calls it for every slot the writeback did not reach — which
   is why s->wb is the single boundary between the two. */
static void sort_slot_release(JSContext *ctx, ValueSlot *v)
{
    if (v->str) { JS_FreeValue(ctx, JS_MKPTR(JS_TAG_STRING, v->str)); v->str = NULL; }
    JS_FreeValue(ctx, v->val); v->val = JS_UNDEFINED;
}

/* DELETED: js_array_sort_end. It performed 23.1.3.30 steps 8-9 — the Set of every sorted element back onto the
   receiver and the DeletePropertyOrThrow of the trailing holes — from fini, a TEARDOWN path. A teardown cannot
   suspend, so a `set` or `deleteProperty` trap with a loop in it had no flow base there; and it could not raise
   the exception a rejecting trap produces either, because fini's result is the machine's value, not a status.
   Those steps are stages 7-9 of js_array_sort_vstep now, and fini only releases.
   It also skipped the Set for any element whose sorted position equalled its original one (`pos == w`). Step 8
   has no such case: `[1,2,3]` behind a Proxy fired NO `set` trap at all where the spec fires three, and a sort
   that permutes nothing on a FROZEN array succeeded silently where the spec throws. `pos` survives only as the
   stable-sort tiebreak it also is. */
/* The sort recognizer is DELETED. Its comment used to say a default sort or a native comparator "stays on rqsort"
   — that sentence WAS the dual system: it named the second implementation the recognizer existed to select. With
   rqsort's body gone and the default ordering folded into js_array_sort_step, there is nothing to select. */

/* DELETED: the rqsort-based js_array_sort. It was a SECOND full implementation of sort — its own collection loop
   with slack growth, its own undefined/hole ordering, its own writeback — duplicating js_array_sort_init /
   _step / _end, which the trampoline already drives. Sort is now that one machine (STEPDEF_ARRAY_SORT), and with
   the default-comparison branch in js_array_sort_step there is no case left for a C body to serve. */
/* sort and toSorted are ONE machine: same comparator drive, same merge, same writeback. The only difference is
   WHAT is sorted — the receiver, or a dense copy of it — so it is the prologue that branches on hdr.arg, not a
   second machine. (toSorted does not use Array[@@species]; it always yields a base Array.) The prologue is in
   three stages because LengthOfArrayLike sits in the middle of it and its ToLength can run user code. */
/* DELETED: js_array_sort_copy. It built toSorted's copy with a C JS_TryGetPropertyInt64 loop, so an element
   accessor with a loop in it had no flow base; and the HasProperty half of that helper is not in the algorithm
   at all — 23.1.3.34 step 6 passes read-through-holes to SortIndexedProperties, whose step 3.b then asserts the
   read is unconditional and 3.c makes it a plain `? Get(obj, Pk)`. On
   `new Proxy([3,1,2], {has: () => false})` that produced [undefined,undefined,undefined] where the spec sorts
   the real elements. The walk is stage 10 of js_array_sort_vstep now. */

static int js_array_sort_vstep(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArraySort *s = st;
    int r;
    if (s->hdr.stage == 0) {
        JSValueConst method = step_arg(&s->hdr, 0);
        JS_FreeValue(ctx, cb_result);
        cb_result = JS_UNDEFINED;
        if (!JS_IsUndefined(method) && check_function(ctx, method))
            return -1;   /* spec: a non-callable comparator throws BEFORE anything is read */
        if (js_array_sort_recv(ctx, s))
            return -1;
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {   /* LengthOfArrayLike, re-entered until it finishes */
        r = step_length_run(ctx, &s->hdr, s->obj, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        if (s->hdr.arg) {
            /* 23.1.3.34 step 4: ArrayCreate(len). toSorted sorts a COPY, so the receiver is never written, and
               the copy is DENSE because read-through-holes gathers every index — what was a hole becomes an
               undefined the sort orders like any other. */
            JSValue *arrp;
            uint32_t count32;
            s->copy = js_allocate_fast_array(ctx, s->len);
            if (JS_IsException(s->copy)) { s->copy = JS_UNDEFINED; return -1; }
            if (js_get_fast_array(ctx, s->obj, &arrp, &count32) && count32 == s->len) {
                int64_t i;
                for (i = 0; i < s->len; i++)
                    arr_dense_put(ctx, s->copy, i, js_dup(arrp[i]));
            } else {
                s->col_i = 0;
                s->hdr.stage = 10;
            }
        }
        if (s->hdr.stage == 2) s->hdr.stage = 11;
    }
    /* step 6 with read-through-holes: SortIndexedProperties step 3.b asserts the read is unconditional, so this
       is a plain `? Get(O, Pk)` at every index — no HasProperty, unlike the skip-holes collect below. */
    while (s->hdr.stage == 10) {
        if (s->col_i >= s->len) { s->hdr.stage = 11; break; }
        r = step_getidx_run(ctx, &s->hdr, s->obj, s->col_i, cb_result, &s->el, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        arr_dense_put(ctx, s->copy, s->col_i, s->el);
        s->el = JS_UNDEFINED;
        s->col_i++;
    }
    if (s->hdr.stage == 11) {
        if (s->hdr.arg) {
            JS_FreeValue(ctx, s->obj);
            s->obj = s->copy;   /* the sort, the writeback and the result are the copy from here on */
            s->copy = JS_UNDEFINED;
        }
        if (s->len > 0) {
            s->array = js_malloc(ctx, (size_t)s->len * sizeof(ValueSlot));
            if (!s->array) return -1;
        }
        s->col_i = 0; s->n = 0;
        s->hdr.stage = 6;
    }
    if (s->hdr.stage == 6) {   /* the collect, re-entered while an index's ask or read runs the page's code */
        r = js_array_sort_collect(ctx, s, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 3;
    }
    if (s->hdr.stage == 3) {
        r = js_array_sort_step(ctx, s, cb_result, (JSValueConst *)&s->cb_args[2], out_cb, out_argc);   /* consumes cb_result */
        cb_result = JS_UNDEFINED;
        if (r < 0) return -1;
        if (r == 5) return r;   /* the default ordering's ToString: the driver coerces and re-enters here */
        if (r != 0) {
            s->cb_args[0] = JS_UNDEFINED;            /* the comparator gets this = undefined */
            s->cb_args[1] = s->method;
            *out_cb = s->cb_args; *out_argc = 2;
            return 3;
        }
        s->wb = 0;
        s->hdr.stage = 7;
    }
    /* 23.1.3.30 steps 8-9: SortIndexedProperties has produced the sorted list, and putting it back is the
       page's code — a Set on an accessor or a `set` trap, a DeletePropertyOrThrow on a `deleteProperty` trap.
       The element is BORROWED across its write and released once it lands, so s->wb is exactly how far the
       teardown must not free. (toSorted's receiver is its own dense copy, so the same walk reaches no page code
       there and its delete loop is empty — one writeback, not two.) */
    while (s->hdr.stage == 7) {
        if (s->wb >= s->n) { s->hdr.stage = 8; break; }
        r = step_setidx_run(ctx, &s->hdr, s->obj, s->wb, s->array[s->wb].val, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        sort_slot_release(ctx, &s->array[s->wb]);
        s->wb++;
    }
    /* the undefineds the collect held back, in the one place the sort order puts them */
    while (s->hdr.stage == 8) {
        if (s->wb >= s->n + s->undefined_count) { s->hdr.stage = 9; break; }
        r = step_setidx_run(ctx, &s->hdr, s->obj, s->wb, JS_UNDEFINED, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->wb++;
    }
    /* step 9: the holes the collect skipped are deleted off the end */
    for (;;) {
        if (s->wb >= s->len) {
            JS_FreeValue(ctx, cb_result);
            DCHECK(s->n + s->undefined_count <= s->len, "the sort gathered more elements than the receiver had");
            return 0;
        }
        r = step_delidx_run(ctx, &s->hdr, s->obj, s->wb, cb_result, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->wb++;
    }
}

static JSValue js_array_sort_vfini(JSContext *ctx, void *st, bool take_result)
{
    JSArraySort *s = st;
    JSValue r;
    int64_t w;
    JS_FreeValue(ctx, s->coerced);   /* a ToString that landed just before an abandon */
    s->coerced = JS_UNDEFINED;
    JS_FreeValue(ctx, s->cmpres);    /* a comparator result whose ToNumber was abandoned part-way */
    s->cmpres = JS_UNDEFINED;
    JS_FreeValue(ctx, s->copy);      /* toSorted's result, if the copy walk was abandoned part-way through */
    JS_FreeValue(ctx, s->el);
    /* every slot the writeback has not consumed: all of them when the machine is abandoned before stage 7, the
       tail of them when a `set` trap threw part-way through it. */
    for (w = s->wb; w < s->n; w++)
        sort_slot_release(ctx, &s->array[w]);
    js_free(ctx, s->array); s->array = NULL;
    js_free(ctx, s->tmp);   s->tmp = NULL;
    r = take_result ? s->obj : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->obj);
    js_free(ctx, s);
    return r;
}

typedef struct JSArrayIteratorData {
    JSValue obj;
    JSIteratorKindEnum kind;
    int64_t idx;   /* LengthOfArrayLike is ToLength, so a source can be longer than a uint32 cursor can count */
} JSArrayIteratorData;

static void js_array_iterator_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        JS_FreeValueRT(rt, it->obj);
        js_free_rt(rt, it);
    }
}

static void js_array_iterator_mark(JSRuntime *rt, JSValueConst val,
                                   JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSArrayIteratorData *it = p->u.array_iterator_data;
    if (it) {
        JS_MarkValue(rt, it->obj, mark_func);
    }
}

static JSValue js_create_array(JSContext *ctx, int len, JSValueConst *tab)
{
    JSValue obj;
    JSObject *p;
    int i;

    obj = JS_NewArray(ctx);
    if (JS_IsException(obj))
        return JS_EXCEPTION;
    if (len > 0) {
        p = JS_VALUE_GET_OBJ(obj);
        if (expand_fast_array(ctx, p, len) < 0) {
            JS_FreeValue(ctx, obj);
            return JS_EXCEPTION;
        }
        p->u.array.count = len;
        for(i = 0; i < len; i++)
            p->u.array.u.values[i] = js_dup(tab[i]);
        /* update the 'length' field */
        set_value(ctx, &p->prop[0].u.value, js_int32(len));
    }
    return obj;
}

static JSValue js_create_array_iterator(JSContext *ctx, JSValueConst this_val,
                                        int argc, JSValueConst *argv, int magic)
{
    JSValue enum_obj, arr;
    JSArrayIteratorData *it;
    JSIteratorKindEnum kind;
    int class_id;

    kind = magic & 3;
    if (magic & 4) {
        /* string iterator case */
        arr = JS_ToStringCheckObject(ctx, this_val);
        class_id = JS_CLASS_STRING_ITERATOR;
    } else {
        arr = JS_ToObject(ctx, this_val);
        class_id = JS_CLASS_ARRAY_ITERATOR;
    }
    if (JS_IsException(arr))
        goto fail;
    enum_obj = JS_NewObjectClass(ctx, class_id);
    if (JS_IsException(enum_obj))
        goto fail;
    it = js_malloc(ctx, sizeof(*it));
    if (!it)
        goto fail1;
    it->obj = arr;
    it->kind = kind;
    it->idx = 0;
    JS_SetOpaqueInternal(enum_obj, it);
    return enum_obj;
 fail1:
    JS_FreeValue(ctx, enum_obj);
 fail:
    JS_FreeValue(ctx, arr);
    return JS_EXCEPTION;
}

static int js_array_iter_next_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSArrayIterNext *s = st;
    JSArrayIteratorData *it;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->obj = JS_UNDEFINED; s->el = JS_UNDEFINED; s->result = JS_UNDEFINED;
        s->len = 0; s->idx = 0; s->kind = JS_ITERATOR_KIND_VALUE;
        it = JS_GetOpaque2(ctx, s->hdr.this_val, JS_CLASS_ARRAY_ITERATOR);
        if (!it) return -1;
        if (JS_IsUndefined(it->obj)) {   /* already exhausted: the closure has returned */
            s->result = js_create_iterator_result(ctx, JS_UNDEFINED, true);
            return JS_IsException(s->result) ? -1 : 0;
        }
        s->obj = js_dup(it->obj);
        s->kind = it->kind;
        {
            JSObject *p = JS_VALUE_GET_OBJ(s->obj);
            if (is_typed_array(p->class_id)) {
                if (typed_array_is_oob(p)) { JS_ThrowTypeErrorArrayBufferOOB(ctx); return -1; }
                s->len = p->u.array.count;
                s->hdr.stage = 2;
            } else {
                s->hdr.stage = 1;
            }
        }
    }
    if (s->hdr.stage == 1) {
        /* LengthOfArrayLike: `? ToLength(? Get(O, "length"))`. js_get_length32 used ToUint32 instead, so a
           `length` of -1 read as 4294967295 rather than clamping to 0. */
        r = step_getlen_run(ctx, &s->hdr, s->obj, JS_ATOM_length, cb_result, &s->len, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        s->hdr.stage = 2;
    }
    if (s->hdr.stage == 2) {
        it = JS_GetOpaque(s->hdr.this_val, JS_CLASS_ARRAY_ITERATOR);
        DCHECK(it != NULL, "the array iterator lost its data across its own length read");
        s->idx = it->idx;
        if (s->idx >= s->len) {
            JS_FreeValue(ctx, it->obj);
            it->obj = JS_UNDEFINED;
            s->result = js_create_iterator_result(ctx, JS_UNDEFINED, true);
            return JS_IsException(s->result) ? -1 : 0;
        }
        it->idx = s->idx + 1;
        if (s->kind == JS_ITERATOR_KIND_KEY) {   /* the key kind reads no element at all */
            s->result = js_create_iterator_result(ctx, js_int64(s->idx), false);
            return JS_IsException(s->result) ? -1 : 0;
        }
        s->hdr.stage = 3;
    }
    DCHECK(s->hdr.stage == 3, "%ArrayIteratorPrototype%.next: unknown stage");
    r = step_getidx_run(ctx, &s->hdr, s->obj, s->idx, cb_result, &s->el, out_cb, out_argc);
    if (r) return r < 0 ? -1 : r;
    if (s->kind == JS_ITERATOR_KIND_VALUE) {
        s->result = js_create_iterator_result(ctx, s->el, false);
        s->el = JS_UNDEFINED;
    } else {
        JSValueConst args[2];
        JSValue num = js_int64(s->idx), pair;
        args[0] = num; args[1] = s->el;
        pair = js_create_array(ctx, 2, args);
        JS_FreeValue(ctx, num);
        JS_FreeValue(ctx, s->el); s->el = JS_UNDEFINED;
        if (JS_IsException(pair)) return -1;
        s->result = js_create_iterator_result(ctx, pair, false);
    }
    return JS_IsException(s->result) ? -1 : 0;
}

static JSValue js_array_iter_next_fini(JSContext *ctx, void *st, bool take_result)
{
    JSArrayIterNext *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->el);
    JS_FreeValue(ctx, s->obj);
    js_free(ctx, s);
    return r;
}


static void js_iterator_wrap_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        JS_FreeValueRT(rt, it->wrapped_iter);
        JS_FreeValueRT(rt, it->wrapped_next);
        js_free_rt(rt, it);
    }
}

static void js_iterator_wrap_mark(JSRuntime *rt, JSValueConst val,
                                  JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorWrapData *it = p->u.iterator_wrap_data;
    if (it) {
        JS_MarkValue(rt, it->wrapped_iter, mark_func);
        JS_MarkValue(rt, it->wrapped_next, mark_func);
    }
}

/* 27.1.4.2.1 steps 1-2, and NOTHING ELSE. The FORWARD is call-site-resolved: do_generic_callee rewrites the
   (receiver, callee) pair to the wrapped record and re-enters, and the drives that hold a record resolve it
   through tramp_unwrap_iter_next — so every spelling of `w.next()` runs the wrapped .next() on the tramp, with
   the arguments dropped exactly as step 4 requires. What is gone is the JS_IteratorNext -> JS_Call this used to
   run: a C activation with no flow base that drove a looping .next() to completion, re-wrapped the forwarded
   result and required it to be an Object, none of which step 4 does.
   Both resolutions decline on a receiver that is not a wrapper, which is precisely the case RequireInternalSlot
   rejects — `%WrapForValidIteratorPrototype%.next.call({})` is a TypeError, and raising it runs no user code and
   has nothing to suspend. So a VALID wrapper arriving here is an unrouted call site, and the DCHECK names it. */
static JSValue js_iterator_wrap_next(JSContext *ctx, JSValueConst this_val,
                                     int argc, JSValueConst *argv,
                                     int *pdone, int magic)
{
    JSIteratorWrapData *it;
    DCHECK(magic == GEN_MAGIC_NEXT, "js_iterator_wrap_next reached with a magic that is not the verbatim forward");
    it = JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_WRAP);
    DCHECK(it == NULL, "a VALID WrapForValidIterator reached the .next C entry — the forward is call-site-resolved, "
                       "so route that call site through do_generic_callee's unwrap rewrite");
    *pdone = false;
    return JS_EXCEPTION;   /* JS_GetOpaque2 already threw RequireInternalSlot's TypeError */
}

/* 27.1.4.2.2, as a step machine so both of its user-code sites suspend. Two fidelity bugs went with the old body:
   it forwarded its own ARGUMENTS to `return` (the spec calls it with none) and it required the result to be an
   Object (step 7 returns the call's result verbatim — only .next's IteratorNext imposes that check). */
static int js_iter_wrap_return_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSIterWrapReturn *s = st;
    int r;

    if (s->hdr.stage == 0) {
        JSIteratorWrapData *it;
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->iter = JS_UNDEFINED; s->result = JS_UNDEFINED;
        s->cb[0] = JS_UNDEFINED; s->cb[1] = JS_UNDEFINED;
        it = JS_GetOpaque2(ctx, s->hdr.this_val, JS_CLASS_ITERATOR_WRAP);
        if (!it) return -1;
        s->iter = js_dup(it->wrapped_iter);
        s->hdr.stage = 1;
    }
    if (s->hdr.stage == 1) {
        r = step_getprop_run(ctx, &s->hdr, s->iter, JS_ATOM_return, cb_result, &s->cb[1], out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        /* GetMethod: undefined or null means there is nothing to forward to (step 6). */
        if (JS_IsUndefined(s->cb[1]) || JS_IsNull(s->cb[1])) {
            s->result = js_create_iterator_result(ctx, JS_UNDEFINED, true);
            return JS_IsException(s->result) ? -1 : 0;
        }
        if (!JS_IsFunction(ctx, s->cb[1])) {
            JS_ThrowTypeError(ctx, "not a function");
            return -1;
        }
        s->cb[0] = js_dup(s->iter);
        s->hdr.stage = 2;
        *out_cb = s->cb; *out_argc = 0;
        return 3;
    }
    DCHECK(s->hdr.stage == 2, "WrapForValidIterator.return: unknown stage");
    s->result = cb_result;
    return 0;
}

static JSValue js_iter_wrap_return_fini(JSContext *ctx, void *st, bool take_result)
{
    JSIterWrapReturn *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (!take_result) JS_FreeValue(ctx, s->result);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    JS_FreeValue(ctx, s->iter);
    js_free(ctx, s);
    return r;
}

static const JSCFunctionListEntry js_iterator_wrap_proto_funcs[] = {
    JS_ITERATOR_NEXT_DEF("next", 0, js_iterator_wrap_next, GEN_MAGIC_NEXT ),
    JS_CFUNC_STEP_DEF("return", 0, STEPDEF_ITER_WRAP_RETURN ),
};


/* Iterator.prototype.constructor's GETTER, which returns %Iterator% out of its closure data. Its setter used to
   share this function under a magic flag; that setter was SetterThatIgnoresPrototypeProperties, which is a step
   machine now (STEPDEF_ITER_SET_CTOR) and shares its implementation with @@toStringTag's instead. */
static JSValue js_iterator_constructor_get(JSContext *ctx,
                                           JSValueConst this_val,
                                           int argc, JSValueConst *argv,
                                           int magic,
                                           JSValueConst *func_data)
{
    return js_dup(func_data[0]);
}

/* 27.1.3.1 steps 1-2. Everything the Iterator constructor does before OrdinaryCreateFromConstructor, and all it
   does: step 3 IS the create, so the declaration carries no body and the machine is the whole constructor.
   The abstract-class test compares against the DECLARATION rather than a C function pointer, because there is no
   C function left to compare against — which is the point. */
static int js_iterator_ctor_precheck(JSContext *ctx, const JSStepHdr *h)
{
    JSValueConst new_target = h->this_val;
    JSObject *p;

    if (JS_TAG_OBJECT != JS_VALUE_GET_TAG(new_target)) {
        JS_ThrowTypeError(ctx, "constructor requires 'new'");
        return -1;
    }
    p = JS_VALUE_GET_OBJ(new_target);
    if (p->class_id == JS_CLASS_C_FUNCTION && p->u.cfunc.cproto == JS_CFUNC_step_ctor
        && p->u.cfunc.magic == STEPDEF_ITERATOR_CTOR) {
        JS_ThrowTypeError(ctx, "abstract class not constructable");
        return -1;
    }
    return 0;
}

typedef struct JSIteratorConcatData {
    uint32_t index : 31; // elements (not pairs!) in values[] array
    uint32_t unused : 1;
    uint32_t count : 31;
    uint32_t running : 1;
    JSValue iter, next, values[]; // array of (object, method) pairs
} JSIteratorConcatData;

static void js_iterator_concat_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        JS_FreeValueRT(rt, it->iter);
        JS_FreeValueRT(rt, it->next);
        for (uint32_t i = it->index; i < it->count; i++)
            JS_FreeValueRT(rt, it->values[i]);
        js_free_rt(rt, it);
    }
}

static void js_iterator_concat_mark(JSRuntime *rt, JSValueConst val,
                                    JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorConcatData *it = p->u.iterator_concat_data;
    if (it) {
        JS_MarkValue(rt, it->iter, mark_func);
        JS_MarkValue(rt, it->next, mark_func);
        for (uint32_t i = it->index; i < it->count; i++)
            JS_MarkValue(rt, it->values[i], mark_func);
    }
}



/* The list walk, as phases. `hdr.this_val` is the JS_CLASS_ITERATOR_CONCAT receiver, so its data is re-read at
   every resume rather than cached across a suspension. `running` is the spec's re-entrancy guard; the teardown
   clears it, which is what makes an abrupt exit leave the iterator usable exactly as the C body's `done:` label
   did. */
enum { CONCAT_PH_HEAD = 0, CONCAT_PH_ITER, CONCAT_PH_NEXTM, CONCAT_PH_CALL,
       CONCAT_PH_DONE, CONCAT_PH_VALUE };

static JSIteratorConcatData *js_iter_concat_data(JSContext *ctx, JSValueConst this_val)
{
    return JS_GetOpaque2(ctx, this_val, JS_CLASS_ITERATOR_CONCAT);
}

/* the current pair is done: drop it and its live iterator, and move on to the next one */
static void js_iter_concat_advance(JSContext *ctx, JSIteratorConcatData *it)
{
    JS_FreeValue(ctx, it->iter);  it->iter = JS_UNDEFINED;
    JS_FreeValue(ctx, it->next);  it->next = JS_UNDEFINED;
    JS_FreeValue(ctx, it->values[it->index + 1]);
    JS_FreeValue(ctx, it->values[it->index + 0]);
    it->index += 2;
}

static int js_iter_concat_next_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSIterConcatNext *s = st;
    JSIteratorConcatData *it;
    int r;

    if (!s->held) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        /* FIRST, before anything that can throw: the teardown frees exactly what the state holds. */
        s->self = JS_UNDEFINED; s->item = JS_UNDEFINED; s->result = JS_UNDEFINED;
        s->cb[0] = JS_UNDEFINED; s->cb[1] = JS_UNDEFINED;
        it = js_iter_concat_data(ctx, s->hdr.this_val);
        if (!it) return -1;
        if (it->running) { JS_ThrowTypeError(ctx, "already running"); return -1; }
        it->running = true;
        s->self = js_dup(s->hdr.this_val);
        s->held = 1;   /* `running` is ours now: fini owes it back */
    }
    it = js_iter_concat_data(ctx, s->self);
    DCHECK(it != NULL, "Iterator.concat: the receiver lost its data mid-walk");

    for (;;) {
        if (s->hdr.stage == CONCAT_PH_HEAD) {
            if (it->index >= it->count) {
                s->result = js_create_iterator_result(ctx, JS_UNDEFINED, true);
                return JS_IsException(s->result) ? -1 : 0;
            }
            if (JS_IsUndefined(it->iter)) {
                /* GetIterator(obj, method): Call(method, obj) — the page's @@iterator */
                s->cb[0] = js_dup(it->values[it->index + 0]);
                s->cb[1] = js_dup(it->values[it->index + 1]);
                s->hdr.stage = CONCAT_PH_ITER;
                *out_cb = s->cb; *out_argc = 0;
                return 3;
            }
            s->hdr.stage = CONCAT_PH_NEXTM;
        }
        if (s->hdr.stage == CONCAT_PH_ITER) {
            if (!JS_IsObject(cb_result)) {   /* GetIterator step 5 */
                JS_FreeValue(ctx, cb_result);
                JS_ThrowTypeErrorNotAnObject(ctx);
                return -1;
            }
            JS_FreeValue(ctx, s->cb[0]); s->cb[0] = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[1]); s->cb[1] = JS_UNDEFINED;
            it->iter = cb_result; cb_result = JS_UNDEFINED;
            s->hdr.stage = CONCAT_PH_NEXTM;
        }
        if (s->hdr.stage == CONCAT_PH_NEXTM) {
            if (JS_IsUndefined(it->next)) {
                JSValue nm = JS_UNDEFINED;
                r = step_getprop_run(ctx, &s->hdr, it->iter, JS_ATOM_next, cb_result, &nm, out_cb, out_argc);
                cb_result = JS_UNDEFINED;
                if (r) return r < 0 ? -1 : r;
                it = js_iter_concat_data(ctx, s->self);   /* the read may have run page code */
                DCHECK(it != NULL, "Iterator.concat: the receiver lost its data across its `next` read");
                JS_FreeValue(ctx, it->next);
                it->next = nm;
            }
            s->cb[0] = js_dup(it->iter);
            s->cb[1] = js_dup(it->next);
            s->hdr.stage = CONCAT_PH_CALL;
            *out_cb = s->cb; *out_argc = 0;
            return 3;
        }
        if (s->hdr.stage == CONCAT_PH_CALL) {
            JS_FreeValue(ctx, s->cb[0]); s->cb[0] = JS_UNDEFINED;
            JS_FreeValue(ctx, s->cb[1]); s->cb[1] = JS_UNDEFINED;
            if (!JS_IsObject(cb_result)) {   /* IteratorNext step 3 */
                JS_FreeValue(ctx, cb_result);
                JS_ThrowTypeError(ctx, "iterator result not an object");
                return -1;
            }
            s->item = cb_result; cb_result = JS_UNDEFINED;
            s->hdr.stage = CONCAT_PH_DONE;
        }
        if (s->hdr.stage == CONCAT_PH_DONE) {
            JSValue dv = JS_UNDEFINED;
            r = step_getprop_run(ctx, &s->hdr, s->item, JS_ATOM_done, cb_result, &dv, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            if (!JS_ToBoolFree(ctx, dv)) {
                s->hdr.stage = CONCAT_PH_VALUE;
            } else {
                JS_FreeValue(ctx, s->item); s->item = JS_UNDEFINED;
                it = js_iter_concat_data(ctx, s->self);   /* the read may have run page code */
                DCHECK(it != NULL, "Iterator.concat: the receiver lost its data across its `done` read");
                js_iter_concat_advance(ctx, it);
                s->hdr.stage = CONCAT_PH_HEAD;
                continue;
            }
        }
        DCHECK(s->hdr.stage == CONCAT_PH_VALUE, "Iterator.concat .next(): unknown stage");
        {
            JSValue vv = JS_UNDEFINED;
            r = step_getprop_run(ctx, &s->hdr, s->item, JS_ATOM_value, cb_result, &vv, out_cb, out_argc);
            cb_result = JS_UNDEFINED;
            if (r) return r < 0 ? -1 : r;
            JS_FreeValue(ctx, s->item); s->item = JS_UNDEFINED;
            s->result = js_create_iterator_result(ctx, vv, false);
            return JS_IsException(s->result) ? -1 : 0;
        }
    }
}

static JSValue js_iter_concat_next_fini(JSContext *ctx, void *st, bool take_result)
{
    JSIterConcatNext *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (s->held) {   /* the re-entrancy guard is lowered however the walk ended */
        JSIteratorConcatData *it = JS_GetOpaque(s->self, JS_CLASS_ITERATOR_CONCAT);
        DCHECK(it != NULL, "Iterator.concat: the receiver lost its data before its guard was lowered");
        it->running = false;
    }
    if (!take_result) JS_FreeValue(ctx, s->result);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    JS_FreeValue(ctx, s->item);
    JS_FreeValue(ctx, s->self);
    js_free(ctx, s);
    return r;
}

static int js_iter_concat_return_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSIterConcatReturn *s = st;
    JSIteratorConcatData *it;
    int r;

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result); cb_result = JS_UNDEFINED;
        s->self = JS_UNDEFINED; s->result = JS_UNDEFINED; s->cb[0] = JS_UNDEFINED; s->cb[1] = JS_UNDEFINED;
        it = js_iter_concat_data(ctx, s->hdr.this_val);
        if (!it) return -1;
        if (it->running) { JS_ThrowTypeError(ctx, "already running"); return -1; }
        s->self = js_dup(s->hdr.this_val);
        s->hdr.stage = JS_IsUndefined(it->iter) ? 3 : 1;   /* nothing live to close */
    }
    if (s->hdr.stage == 1) {
        JSValue rm = JS_UNDEFINED;
        it = js_iter_concat_data(ctx, s->self);
        DCHECK(it != NULL, "Iterator.concat .return(): the receiver lost its data");
        r = step_getprop_run(ctx, &s->hdr, it->iter, JS_ATOM_return, cb_result, &rm, out_cb, out_argc);
        cb_result = JS_UNDEFINED;
        if (r) return r < 0 ? -1 : r;
        it = js_iter_concat_data(ctx, s->self);
        DCHECK(it != NULL, "Iterator.concat .return(): the receiver lost its data across its `return` read");
        /* the C body called whatever the read produced and let JS_CallFree raise on a non-callable, so a nullish
           `return` was a TypeError rather than a no-op. That is what it did, and it is kept: this is not
           GetMethod — 27.1.4.1.2's concat iterator calls the property it read. */
        s->cb[0] = js_dup(it->iter);
        s->cb[1] = rm;
        it->running = true;
        s->held = 1;
        s->hdr.stage = 2;
        *out_cb = s->cb; *out_argc = 0;
        return 3;
    }
    if (s->hdr.stage == 2) {
        it = js_iter_concat_data(ctx, s->self);
        DCHECK(it != NULL, "Iterator.concat .return(): the receiver lost its data across its `return` call");
        it->running = false;
        s->held = 0;
        s->result = cb_result;
        s->hdr.stage = 3;
        if (JS_IsException(s->result)) { s->result = JS_UNDEFINED; return -1; }
    }
    DCHECK(s->hdr.stage == 3, "Iterator.concat .return(): unknown stage");
    it = js_iter_concat_data(ctx, s->self);
    DCHECK(it != NULL, "Iterator.concat .return(): the receiver lost its data before its release");
    while (it->index < it->count) {
        JSValue *pv = &it->values[it->index++];
        JS_FreeValue(ctx, *pv);
        *pv = JS_UNDEFINED;
    }
    JS_FreeValue(ctx, it->iter);  it->iter = JS_UNDEFINED;
    JS_FreeValue(ctx, it->next);  it->next = JS_UNDEFINED;
    return 0;
}

static JSValue js_iter_concat_return_fini(JSContext *ctx, void *st, bool take_result)
{
    JSIterConcatReturn *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    int i;
    if (s->held) {
        JSIteratorConcatData *it = JS_GetOpaque(s->self, JS_CLASS_ITERATOR_CONCAT);
        DCHECK(it != NULL, "Iterator.concat: the receiver lost its data before its guard was lowered");
        it->running = false;
    }
    if (!take_result) JS_FreeValue(ctx, s->result);
    for (i = 0; i < 2; i++) JS_FreeValue(ctx, s->cb[i]);
    JS_FreeValue(ctx, s->self);
    js_free(ctx, s);
    return r;
}

static const JSCFunctionListEntry js_iterator_concat_proto_funcs[] = {
    JS_CFUNC_STEP_DEF("next", 1, STEPDEF_ITER_CONCAT_NEXT ),
    JS_CFUNC_STEP_DEF("return", 1, STEPDEF_ITER_CONCAT_RETURN ),
    JS_PROP_STRING_DEF("[Symbol.toStringTag]", "Iterator Concat", JS_PROP_CONFIGURABLE ),
};

static JSValue js_iterator_concat(JSContext *ctx, JSValueConst this_val,
                                  int argc, JSValueConst *argv)
{
    JSIteratorConcatData *it;
    JSValue obj, method;

    it = js_malloc(ctx, sizeof(*it) + 2*argc * sizeof(it->values[0]));
    if (!it)
        return JS_EXCEPTION;
    it->running = false;
    it->index = 0;
    it->count = 0;
    it->iter = JS_UNDEFINED;
    it->next = JS_UNDEFINED;
    for (int i = 0; i < argc; i++) {
        JSValueConst obj = argv[i];
        if (!JS_IsObject(obj)) {
            JS_ThrowTypeErrorNotAnObject(ctx);
            goto fail;
        }
        method = JS_GetProperty(ctx, obj, JS_ATOM_Symbol_iterator);
        if (JS_IsException(method))
            goto fail;
        if (!JS_IsFunction(ctx, method)) {
            JS_ThrowTypeErrorNotAFunction(ctx);
            JS_FreeValue(ctx, method);
            goto fail;
        }
        it->values[it->count++] = js_dup(obj);
        it->values[it->count++] = method;
    }
    obj = JS_NewObjectClass(ctx, JS_CLASS_ITERATOR_CONCAT);
    if (JS_IsException(obj))
        goto fail;
    JS_SetOpaqueInternal(obj, it);
    return obj;
fail:
    for (uint32_t i = 0; i < it->count; i++)
        JS_FreeValue(ctx, it->values[i]);
    js_free(ctx, it);
    return JS_EXCEPTION;
}

/* DELETED: js_iterator_from. Its body was already only a DFAIL — the whole of 27.1.3.1 is do_iterfrom_tramp —
   and with the walk declared at the definition no pointer names it. */

static int check_iterator(JSContext *ctx, JSValueConst obj)
{
    if (!JS_IsObject(obj)) {
        JS_ThrowTypeErrorNotAnObject(ctx);
        return -1;
    }
    return 0;
}

static JSValue js_async_dispose_to_undef(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv,
                                         int magic, JSValueConst *func_data);

static JSValue js_iterator_proto_dispose(JSContext *ctx, JSValueConst this_val,
                                         int argc, JSValueConst *argv)
{
    JSValue method;

    method = JS_GetProperty(ctx, this_val, JS_ATOM_return);
    if (JS_IsException(method))
        return JS_EXCEPTION;
    if (JS_IsUndefined(method))
        return JS_UNDEFINED;
    return JS_CallFree(ctx, method, this_val, 0, NULL);
}

static JSValue js_async_iterator_proto_dispose(JSContext *ctx,
                                               JSValueConst this_val,
                                               int argc, JSValueConst *argv)
{
    JSValue method, ret, promise, undef_fn, then_args[2], result;
    JSValue undef = JS_UNDEFINED;

    method = JS_GetProperty(ctx, this_val, JS_ATOM_return);
    if (JS_IsException(method)) {
        JSValue exc = JS_GetException(ctx);
        JSValue p = js_promise_resolve_native(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        JS_FreeValue(ctx, exc);
        return p;
    }
    if (JS_IsUndefined(method)) {
        return js_promise_resolve_native(ctx, ctx->promise_ctor, 1, vc(&undef), 0);
    }
    ret = JS_Call(ctx, method, this_val, 0, NULL);
    JS_FreeValue(ctx, method);
    if (JS_IsException(ret)) {
        JSValue exc = JS_GetException(ctx);
        JSValue p = js_promise_resolve_native(ctx, ctx->promise_ctor, 1, vc(&exc), 1);
        JS_FreeValue(ctx, exc);
        return p;
    }
    /* Wrap in Promise.resolve(ret).then(() => undefined) */
    promise = js_promise_resolve_native(ctx, ctx->promise_ctor, 1, vc(&ret), 0);
    JS_FreeValue(ctx, ret);
    if (JS_IsException(promise))
        return promise;
    undef_fn = JS_NewCFunctionData(ctx, js_async_dispose_to_undef, 0, 0, 0,
                                   NULL);
    if (JS_IsException(undef_fn)) {
        JS_FreeValue(ctx, promise);
        return JS_EXCEPTION;
    }
    then_args[0] = undef_fn;
    /* this is an AWAIT — PerformPromiseThen on a capability — not Promise.prototype.then, and `promise` is the
       engine's own PromiseResolve(%Promise%, ret). Spelling it as an Invoke made it read a property and CALL the
       method, which since `then` became a step machine is a builtin driven from C. */
    then_args[1] = JS_UNDEFINED;
    result = js_promise_then_native(ctx, promise, vc(then_args));
    JS_FreeValue(ctx, undef_fn);
    JS_FreeValue(ctx, promise);
    return result;
}

static JSValue js_iterator_proto_iterator(JSContext *ctx, JSValueConst this_val,
                                          int argc, JSValueConst *argv)
{
    return js_dup(this_val);
}

static JSValue js_iterator_proto_get_toStringTag(JSContext *ctx, JSValueConst this_val)
{
    return JS_AtomToString(ctx, JS_ATOM_Iterator);
}

/* Iterator.prototype.{drop,take,map,filter,flatMap}: create the helper object over `this` (the source iterator).
   No drive-to-completion — pure object creation; the source is iterated lazily by the helper's .next(). */
/* IfAbruptCloseIterator: close the source. The `return` is the PAGE's code whatever the source is — a generator's
   finally, an accessor, a proxy trap, a plain method with a loop in it — so it runs on the tramp: DEFER it to the
   interpreter caller via ctx->pending_close_iter, whose exception label owns the routing. Asking here what kind of
   iterator this is (and closing a non-generator inline with JS_IteratorClose) was the fallback that drove the
   page's `return` from C. Shared by the body's own failures and by the coerce-then-compute machine's
   abrupt-coercion hook, because the spec makes no distinction: step 5 of take/drop closes for BOTH. */
static void js_iterator_helper_close(JSContext *ctx, JSValueConst this_val, int magic)
{
    DCHECK(JS_IsUninitialized(ctx->pending_close_iter),
           "pending_close_iter already set — a nested IfAbruptCloseIterator needs a queue");
    ctx->pending_close_iter = js_dup(this_val);
}

/* The build, with GetIteratorDirect's nextMethod already in hand (TRANSFERRED) and `limit` already primitive.
   Everything it does is spec arithmetic and object construction: no page code left in it. */
/* take/drop steps 3-7: ToNumber (already performed — `limit` is primitive here), then the NaN and negative
   RangeErrors, then ToIntegerOrInfinity. ALL of it precedes GetIteratorDirect, which is why it cannot live in
   the build: reading `next` first made the read observable before a limit that the spec rejects, and made its
   throw win over the RangeError. */
static int js_iter_helper_limit(JSContext *ctx, JSValueConst limit, int64_t *pcount)
{
    JSValue v;
    double dlimit;

    v = JS_ToNumber(ctx, limit);   /* the operand is primitive: this invokes nothing, it only throws */
    if (JS_IsException(v))
        return -1;
    if (JS_ToFloat64(ctx, &dlimit, v)) {
        JS_FreeValue(ctx, v);
        return -1;
    }
    if (isnan(dlimit)) {
        JS_FreeValue(ctx, v);
        goto range_error;
    }
    if (!isfinite(dlimit)) {
        JS_FreeValue(ctx, v);
        if (dlimit < 0)
            goto range_error;
        *pcount = MAX_SAFE_INTEGER;
        return 0;
    }
    v = JS_ToIntegerFree(ctx, v);
    if (JS_IsException(v))
        return -1;
    if (JS_ToInt64Free(ctx, pcount, v))
        return -1;
    if (*pcount < 0)
        goto range_error;
    return 0;
range_error:
    JS_ThrowRangeError(ctx, "must be positive");
    return -1;
}

static JSValue js_iter_helper_build(JSContext *ctx, JSValueConst this_val,
                                    JSValueConst arg0, int64_t count, JSValue method, int magic)
{
    JSValueConst func;
    JSValue obj;
    JSIteratorHelperData *it;

    func = JS_UNDEFINED;

    switch(magic) {
    case JS_ITERATOR_HELPER_KIND_DROP:
    case JS_ITERATOR_HELPER_KIND_TAKE:
        break;
    case JS_ITERATOR_HELPER_KIND_FILTER:
    case JS_ITERATOR_HELPER_KIND_FLAT_MAP:
    case JS_ITERATOR_HELPER_KIND_MAP:
        func = arg0;
        break;
    default:
        abort();
        break;
    }

    obj = JS_NewObjectClass(ctx, JS_CLASS_ITERATOR_HELPER);
    if (JS_IsException(obj)) {
        JS_FreeValue(ctx, method);
        goto fail;
    }
    it = js_malloc(ctx, sizeof(*it));
    if (!it) {
        JS_FreeValue(ctx, obj);
        JS_FreeValue(ctx, method);
        goto fail;
    }
    memset(it, 0, sizeof(*it));
    it->kind = magic;
    it->obj = js_dup(this_val);
    it->func = js_dup(func);
    it->next = method;
    it->inner = JS_UNDEFINED;
    it->inner_next = JS_UNDEFINED;
    it->cb_value = JS_UNDEFINED;
    it->res_obj = JS_UNDEFINED;   /* the memset zeroes it, and a zero JSValue is not UNDEFINED */
    it->count = count;
    it->executing = 0;
    it->done = 0;
    JS_SetOpaqueInternal(obj, it);
    return obj;
fail:
    /* the close is the DEFINITION's onerror hook, which runs on any -1 from the step — so the body only owes the
       method it was handed and the exception. */
    JS_FreeValue(ctx, method);
    return JS_EXCEPTION;
}

/* stage 0: 27.1.4.3/.5 steps 1-2 (the receiver, then the argument), and take/drop's limit ToPrimitive.
   stage 1: the coerced limit arrives.
   stage 2: GetIteratorDirect's `next` read arrives, and the helper is built. */
static int js_iter_helper_new_step(JSContext *ctx, void *st, JSValue cb_result, JSValue **out_cb, int *out_argc)
{
    JSIterHelperNew *s = st;
    int magic = s->hdr.def->body_magic;
    bool has_limit = (magic == JS_ITERATOR_HELPER_KIND_TAKE || magic == JS_ITERATOR_HELPER_KIND_DROP);

    if (s->hdr.stage == 0) {
        JS_FreeValue(ctx, cb_result);
        /* 27.1.4.3/.5 step 1-2's TypeError precedes everything and closes NOTHING, so it is raised while
           `coercing` is still clear — that flag is what tramp_step_state_free consults before calling the
           definition's onerror, so it is exactly "an abrupt completion from here on owes the IfAbruptClose". */
        if (check_iterator(ctx, s->hdr.this_val) < 0)
            return -1;
        s->hdr.coercing = 1;   /* every failure below this line closes the source */
        s->limit = js_dup(step_arg(&s->hdr, 0));
        s->hdr.stage = 1;
        if (has_limit) {
            if (JS_VALUE_GET_TAG(s->limit) == JS_TAG_OBJECT) {
                s->cb[0] = s->limit;   /* borrowed: the state holds the reference */
                *out_cb = s->cb; *out_argc = HINT_NUMBER;
                return 5;
            }
        } else if (check_function(ctx, s->limit)) {
            return -1;   /* 27.1.4.5 step 3: a non-callable mapper closes the source */
        }
    } else if (s->hdr.stage == 1) {
        DCHECK(has_limit, "a non-coercing iterator-helper factory was resumed with a primitive");
        JS_FreeValue(ctx, s->limit);
        s->limit = cb_result;   /* the primitive REPLACES the argument the validation will read */
        cb_result = JS_UNDEFINED;
    }
    s->hdr.coercing = 1;   /* the TOPRIMITIVE resume clears it; the obligation is unchanged */
    if (s->hdr.stage != 2) {
        /* steps 3-7 BEFORE step 8's GetIteratorDirect: the limit's NaN/negative RangeErrors precede the `next`
           read, so a rejected limit never makes that read observable and a throwing `next` getter never wins
           over the RangeError. */
        if (has_limit && js_iter_helper_limit(ctx, s->limit, &s->count) < 0)
            return -1;
        s->hdr.stage = 2;
        cb_result = JS_UNDEFINED;
    }
    {
        JSValue method = JS_UNDEFINED;
        int r = step_getprop_run(ctx, &s->hdr, s->hdr.this_val, JS_ATOM_next, cb_result,
                                 &method, out_cb, out_argc);
        if (r != 0)
            return r;   /* 6 = the read is in flight, -1 = it threw (onerror closes the source) */
        s->result = js_iter_helper_build(ctx, s->hdr.this_val, s->limit, s->count, method, magic);
        if (JS_IsException(s->result)) { s->result = JS_UNDEFINED; return -1; }
        s->hdr.coercing = 0;
        return 0;
    }
}

static JSValue js_iter_helper_new_fini(JSContext *ctx, void *st, bool take_result)
{
    JSIterHelperNew *s = st;
    JSValue r = take_result ? s->result : JS_UNDEFINED;
    if (!take_result) JS_FreeValue(ctx, s->result);
    JS_FreeValue(ctx, s->limit);
    js_free(ctx, s);
    return r;
}

/* Resumable driver for a lazy Iterator Helper's .next() over a GENERATOR source: `res` = the source .next()
   {value,done} from the previous tramp drive (UNINITIALIZED at the start; owned by this fn). On DONE *out receives
   the {value,done} to deliver. Returns 0 = DONE, 1 = DRIVE the source .next() again. EVERY kind runs here — the
   line that said only DROP was built, and that the rest used a plain-iterator C path, outlived both. */
/* IfAbruptCloseIterator: close a helper's SOURCE on an abrupt completion (mapper/predicate throw), PRESERVING the
   pending exception. Every source closes on the tramp — the exception label saves and restores the exception
   across the close and discards the close's own throw, spec-correct. Call with the pending exception set, then
   return -1. */
static void iter_helper_close_source_abrupt(JSContext *ctx, JSIteratorHelperData *it)
{
    DCHECK(JS_IsUninitialized(ctx->pending_close_iter),
           "pending_close_iter already set — a nested IfAbruptCloseIterator needs a queue");
    ctx->pending_close_iter = js_dup(it->obj);
}

static int js_iter_helper_step(JSContext *ctx, JSIteratorHelperData *it, JSValue res, JSValue *out)
{
    *out = JS_UNDEFINED;
    if (it->resume_pc == ITHP_START && it->done) {
        /* An EXHAUSTED helper answers {undefined, true} and drives nothing. It is answered HERE, at the start of
           a drive, rather than declined back to js_iterator_helper_next's C entry: a case a recognizer hands to
           the other implementation is a case that implementation has to keep existing for, whether or not any
           page code is in it. `done` is also set DURING a drive (take's limit sets it before its close), which
           is why this asks at the START and not on every re-entry. */
        *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
        return JS_IsException(*out) ? -1 : 0;
    }
    switch (it->resume_pc) {
    case ITHP_START:   /* res is UNINITIALIZED — decide the first drive */
        switch (it->kind) {
        case JS_ITERATOR_HELPER_KIND_DROP:
            if (it->count > 0) { it->count--; it->resume_pc = ITHP_DROP_SKIP; }
            else it->resume_pc = ITHP_EMIT;
            return 1;
        case JS_ITERATOR_HELPER_KIND_TAKE:
            if (it->count == 0) {
                /* limit reached: 7.4.9 IteratorClose on the source, then deliver done. It is parked on the tramp
                   for EVERY source kind — GetMethod(source, "return") and the Call of what it produced are both
                   the page's code, and the Call reaches whatever the source is through the convergence point.
                   This used to ask whether the source was a GENERATOR and close anything else inline with
                   JS_IteratorClose, which is one more selector picking a C path: a PLAIN source's looping
                   `return` drove to completion, and `x.map(f).filter(g)` — a helper whose source is a helper —
                   went through that C close as well. */
                it->done = 1;
                it->drive_close = 1;
                it->resume_pc = ITHP_TAKE_CLOSE;
                return 1;
            }
            it->count--;
            it->resume_pc = ITHP_EMIT;
            return 1;
        case JS_ITERATOR_HELPER_KIND_MAP:
        case JS_ITERATOR_HELPER_KIND_FILTER:
            it->resume_pc = ITHP_EMIT;   /* drive the source; EMIT applies the callback */
            return 1;
        case JS_ITERATOR_HELPER_KIND_FLAT_MAP:
            if (!JS_IsUndefined(it->inner)) { it->drive_inner = 1; it->resume_pc = ITHP_FLATMAP_INNER; }   /* continue the active inner */
            else { it->drive_inner = 0; it->resume_pc = ITHP_FLATMAP_SRC; }   /* pull the next source value */
            return 1;
        default:
            DFAIL("js_iter_helper_step: kind not built on the tramp");
            return -1;
        }
    case ITHP_DROP_SKIP:
        /* IteratorComplete on the source result: `Get(res, "done")` is the page's code on a hand-written source,
           so it is a REQUEST and the result parks on the helper across it. */
        if (!JS_IsObject(res)) {   /* 7.4.2 step 3, stated rather than left to fall out of the read */
            JS_FreeValue(ctx, res);
            JS_ThrowTypeError(ctx, "iterator result not an object");
            return -1;
        }
        DCHECK(JS_IsUndefined(it->res_obj), "the helper is already unpacking a result");
        it->res_obj = res;
        it->resume_pc = ITHP_SKIP_DONE; it->read_atom = JS_ATOM_done;
        return 6;
    case ITHP_SKIP_DONE: {
        int d = JS_ToBoolFree(ctx, res);
        JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
        if (d) { it->done = 1; it->resume_pc = ITHP_START; *out = js_create_iterator_result(ctx, JS_UNDEFINED, true); return JS_IsException(*out) ? -1 : 0; }
        if (it->count > 0) {
            /* another element to drop: the NEXT drive re-enters the unpack, not this half of it. The resume point
               has to be set back explicitly now that the read is a suspension — leaving it at SKIP_DONE fed the
               next result OBJECT to ToBoolean, which is truthy, and drop() reported done. */
            it->count--;
            it->resume_pc = ITHP_DROP_SKIP;
            return 1;
        }
        it->resume_pc = ITHP_EMIT;
        return 1;
    }
    case ITHP_TAKE_CLOSE:   /* take limit: the source's .return() (finally) ran on the tramp; discard it, deliver done */
        JS_FreeValue(ctx, res);
        it->resume_pc = ITHP_START;
        *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
        return JS_IsException(*out) ? -1 : 0;
    case ITHP_EMIT:
        if (!JS_IsObject(res)) {   /* 7.4.2 step 3 */
            JS_FreeValue(ctx, res);
            JS_ThrowTypeError(ctx, "iterator result not an object");
            return -1;
        }
        DCHECK(JS_IsUndefined(it->res_obj), "the helper is already unpacking a result");
        it->res_obj = res;
        it->resume_pc = ITHP_EMIT_DONE; it->read_atom = JS_ATOM_done;
        return 6;   /* IteratorComplete */
    case ITHP_EMIT_DONE: {
        int d = JS_ToBoolFree(ctx, res);
        if (d) {
            it->done = 1; it->resume_pc = ITHP_START;
            JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
            *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
            return JS_IsException(*out) ? -1 : 0;
        }
        /* spec: value = IteratorValue(result) — the READ fires a value getter, so it is a request too; a fresh
           {value, done:false} is yielded afterwards and the source result never passes through unread. */
        it->resume_pc = ITHP_EMIT_VALUE; it->read_atom = JS_ATOM_value;
        return 6;
    }
    case ITHP_EMIT_VALUE: {
        JSValue v = res;
        JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
        if (it->kind == JS_ITERATOR_HELPER_KIND_DROP || it->kind == JS_ITERATOR_HELPER_KIND_TAKE) {
            it->resume_pc = ITHP_START;
            *out = js_create_iterator_result(ctx, v, false);   /* consumes v */
            return JS_IsException(*out) ? -1 : 0;
        }
        /* MAP / FILTER: the callback must run ON THE TRAMP so a loop inside it parks like any other flow. Hold the
           source value on the helper and hand the call back to do_iter_helper_step (st==3); it re-enters here at
           ITHP_CB_DONE with the callback's result in `res`. */
        DCHECK(JS_IsUndefined(it->cb_value), "helper callback value already held — a step overlapped its callback");
        it->cb_value = v;
        it->resume_pc = ITHP_CB_DONE;
        return 3;   /* CALL it->func(v, count++) on the tramp */
    }
    case ITHP_CB_DONE: {
        /* `res` is the map/filter callback's RESULT (it ran on the tramp). */
        {
            JSValue v = it->cb_value;
            JSValue fret = res;
            it->cb_value = JS_UNDEFINED;
            if (JS_IsException(fret)) {   /* IfAbruptCloseIterator: mapper/predicate threw -> close the source */
                JS_FreeValue(ctx, v);
                it->done = 1;
                iter_helper_close_source_abrupt(ctx, it);
                return -1;
            }
            if (it->kind == JS_ITERATOR_HELPER_KIND_MAP) {
                JS_FreeValue(ctx, v);
                it->resume_pc = ITHP_START;
                *out = js_create_iterator_result(ctx, fret, false);   /* consumes fret */
                return JS_IsException(*out) ? -1 : 0;
            }
            /* FILTER: emit v if the predicate is truthy, else skip and drive the source again. */
            if (JS_ToBoolFree(ctx, fret)) {
                it->resume_pc = ITHP_START;
                *out = js_create_iterator_result(ctx, v, false);   /* consumes v */
                return JS_IsException(*out) ? -1 : 0;
            }
            JS_FreeValue(ctx, v);
            it->resume_pc = ITHP_EMIT;   /* skip: re-drive the source, re-apply the predicate */
            return 1;
        }
    }
    case ITHP_FLATMAP_SRC:
        /* res = SOURCE {value,done}: the same unpack the emit does, so the same two requests. */
        if (!JS_IsObject(res)) {   /* 7.4.2 step 3 */
            JS_FreeValue(ctx, res);
            JS_ThrowTypeError(ctx, "iterator result not an object");
            return -1;
        }
        DCHECK(JS_IsUndefined(it->res_obj), "the helper is already unpacking a result");
        it->res_obj = res;
        it->resume_pc = ITHP_FLATMAP_DONE; it->read_atom = JS_ATOM_done;
        return 6;   /* IteratorComplete */
    case ITHP_FLATMAP_DONE: {
        int d = JS_ToBoolFree(ctx, res);
        if (d) {
            it->done = 1; it->resume_pc = ITHP_START;
            JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
            *out = js_create_iterator_result(ctx, JS_UNDEFINED, true);
            return JS_IsException(*out) ? -1 : 0;
        }
        it->resume_pc = ITHP_FLATMAP_VALUE; it->read_atom = JS_ATOM_value;
        return 6;   /* IteratorValue */
    }
    case ITHP_FLATMAP_VALUE: {
        JSValue v = res;
        JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
        /* the mapper must run ON THE TRAMP (a loop inside it has to park): hold the element, hand the call to
           do_iter_helper_step, and resume at ITHP_FLATMAP_CB with its result. */
        DCHECK(JS_IsUndefined(it->cb_value), "flatMap mapper value already held");
        it->cb_value = v;
        it->resume_pc = ITHP_FLATMAP_CB;
        return 3;
    }
    case ITHP_FLATMAP_CB: {
        {
            JSValue v = it->cb_value, mapped = res, method, iter;
            it->cb_value = JS_UNDEFINED;
            JS_FreeValue(ctx, v);
            /* IfAbruptCloseIterator on the mapper throw, a non-object result (GetIteratorFlattenable rejects it), and a
               throwing @@iterator: each closes the SOURCE preserving the exception. */
            if (JS_IsException(mapped)) { it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
            if (!JS_IsObject(mapped)) { JS_FreeValue(ctx, mapped); JS_ThrowTypeError(ctx, "flatMap mapper did not return an object"); it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
            /* GetIteratorFlattenable step 4: `? GetMethod(obj, @@iterator)`. A read on the page's object, so a
               request; the object parks in res_obj across it like every other read this machine makes. */
            DCHECK(JS_IsUndefined(it->res_obj), "the helper is already holding a read target");
            it->res_obj = mapped;
            it->resume_pc = ITHP_FLATMAP_ITER_READ; it->read_atom = JS_ATOM_Symbol_iterator;
            it->read_closes_source = 1;
            return 6;
        }
    }
    case ITHP_FLATMAP_ITER_READ: {
        it->read_closes_source = 0;
        JSValue mapped = it->res_obj; it->res_obj = JS_UNDEFINED;
        if (JS_IsException(res)) { JS_FreeValue(ctx, mapped); it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
        if (JS_IsNull(res) || JS_IsUndefined(res)) {
            /* no @@iterator: the mapped object IS the iterator (GetIteratorFlattenable's step 5.a). */
            JS_FreeValue(ctx, res);
            it->inner = mapped;
            it->resume_pc = ITHP_FLATMAP_NEXT_READ; it->read_atom = JS_ATOM_next;
            it->read_closes_source = 1;
            DCHECK(JS_IsUndefined(it->res_obj), "the helper is already holding a read target");
            it->res_obj = js_dup(it->inner);
            return 6;
        }
        /* the method CALL. It used to be JS_GetIterator2 from C for everything except a generator function,
           which one call site recognized so it could route the create — so an ordinary `[Symbol.iterator]() {…}`
           with a loop in it drove to completion. It is an ordinary call at the one call entry now, which is where
           the create question is already asked for every callee kind. */
        it->inner = mapped;   /* `this` (owned; transferred to the stack by the caller) */
        it->inner_next = res; /* the method (owned) */
        it->resume_pc = ITHP_FLATMAP_ITER_CALL;
        return 7;
    }
    case ITHP_FLATMAP_ITER_CALL: {
        if (JS_IsException(res)) { it->done = 1; iter_helper_close_source_abrupt(ctx, it); return -1; }
        if (!JS_IsObject(res)) {   /* GetIteratorFromMethod step 3 */
            JS_FreeValue(ctx, res);
            JS_ThrowTypeErrorNotAnObject(ctx);
            it->done = 1; iter_helper_close_source_abrupt(ctx, it);
            return -1;
        }
        it->inner = res;
        it->resume_pc = ITHP_FLATMAP_NEXT_READ; it->read_atom = JS_ATOM_next;
        it->read_closes_source = 1;
        DCHECK(JS_IsUndefined(it->res_obj), "the helper is already holding a read target");
        it->res_obj = js_dup(it->inner);
        return 6;
    }
    case ITHP_FLATMAP_NEXT_READ: {
        it->read_closes_source = 0;
        JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
        if (JS_IsException(res)) {
            JS_FreeValue(ctx, it->inner); it->inner = JS_UNDEFINED;
            it->done = 1; iter_helper_close_source_abrupt(ctx, it);
            return -1;
        }
        it->inner_next = res;
        it->drive_inner = 1;
        it->resume_pc = ITHP_FLATMAP_INNER;
        return 1;   /* drive the inner iterator */
    }
    case ITHP_FLATMAP_INNER:
        /* res = INNER {value,done}: 27.1.4.5's inner loop does IteratorStepValue — IteratorComplete then
           IteratorValue — and YIELDS the value, so the helper builds a fresh CreateIterResultObject around it.
           Emitting the inner's own result OBJECT instead (what this did) leaked the delegate's object identity
           through `helper.next()`, and moved the `value` read from inside the helper to whoever consumed it. */
        if (!JS_IsObject(res)) {   /* 7.4.2 step 3 */
            JS_FreeValue(ctx, res);
            JS_ThrowTypeError(ctx, "iterator result not an object");
            return -1;
        }
        DCHECK(JS_IsUndefined(it->res_obj), "the helper is already unpacking a result");
        it->res_obj = res;
        it->resume_pc = ITHP_INNER_DONE; it->read_atom = JS_ATOM_done;
        return 6;
    case ITHP_INNER_DONE: {
        int d = JS_ToBoolFree(ctx, res);
        if (d) {   /* inner exhausted: a naturally-done iterator needs no close; go back to the source */
            JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
            JS_FreeValue(ctx, it->inner); it->inner = JS_UNDEFINED;
            JS_FreeValue(ctx, it->inner_next); it->inner_next = JS_UNDEFINED;
            it->drive_inner = 0;
            it->resume_pc = ITHP_FLATMAP_SRC;
            return 1;   /* drive the source for the next inner iterable */
        }
        it->resume_pc = ITHP_INNER_VALUE; it->read_atom = JS_ATOM_value;
        return 6;   /* IteratorValue on the inner's result — a request like every other keyed read */
    }
    case ITHP_INNER_VALUE: {
        JS_FreeValue(ctx, it->res_obj); it->res_obj = JS_UNDEFINED;
        it->resume_pc = ITHP_START;   /* the next .next() continues this inner (START re-checks it->inner) */
        *out = js_create_iterator_result(ctx, res, false);   /* a FRESH result, per Yield; consumes res */
        return JS_IsException(*out) ? -1 : 0;
    }
    }
    DFAIL("js_iter_helper_step: bad resume_pc");
    return -1;
}

/* Can a drive BEGIN on this receiver? Not which builtin the callee is — that is the declaration's answer now
   (tramp_is_iter_drive), and comparing against js_iterator_helper_next's address was the identity test the
   recognizer ban is about. What is left is about the RECEIVER: `.next` is reachable off %IteratorHelperPrototype%
   with any `this`, and 27.1.4 requires the internal slot; and a helper that is already driving cannot be
   re-entered, which is GeneratorValidate's TypeError. Both answers belong to js_call_c_function's iterdrive arm,
   which is where a decline lands — the drive itself cannot give the second one, because entry is what raises the
   flag it tests. */
/* The two answers a DECLINED drive owes, which is everything js_iterator_helper_next had left. Both are spec
   answers and neither is an algorithm: 27.1.4 requires the internal slot, and a helper already driving is
   GeneratorValidate's TypeError. Reaching here for any OTHER reason is an unrouted call site, and the DCHECK
   says so rather than letting it read as a TypeError the page asked for. */
static JSValue js_iter_helper_declined(JSContext *ctx, JSValueConst this_obj)
{
    JSObject *hp = JS_VALUE_GET_TAG(this_obj) == JS_TAG_OBJECT ? JS_VALUE_GET_OBJ(this_obj) : NULL;
    JSIteratorHelperData *hit = (hp && hp->class_id == JS_CLASS_ITERATOR_HELPER)
                                ? hp->u.iterator_helper_data : NULL;
    DCHECK(hit == NULL || hit->executing,
           "a drivable Iterator Helper .next() was invoked outside the interpreter's dispatch — route that call "
           "site onto do_iter_helper_tramp; there is no second driver");
    if (!hit)
        return JS_ThrowTypeError(ctx, "not an Iterator Helper");
    return JS_ThrowTypeError(ctx, "Iterator Helper is already running");
}

static bool iter_helper_drive_ready(JSValueConst func, JSValueConst this_val)
{
    JSObject *tp;
    JSIteratorHelperData *it;
    if (!tramp_is_iter_drive(func)) return false;
    if (JS_VALUE_GET_TAG(this_val) != JS_TAG_OBJECT) return false;
    tp = JS_VALUE_GET_OBJ(this_val);
    if (tp->class_id != JS_CLASS_ITERATOR_HELPER) return false;
    it = tp->u.iterator_helper_data;
    if (!it || it->executing) return false;
    return true;
}

static void js_iterator_helper_finalizer(JSRuntime *rt, JSValueConst val)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        JS_FreeValueRT(rt, it->obj);
        JS_FreeValueRT(rt, it->func);
        JS_FreeValueRT(rt, it->next);
        JS_FreeValueRT(rt, it->inner);
        JS_FreeValueRT(rt, it->inner_next);
        JS_FreeValueRT(rt, it->cb_value);
        JS_FreeValueRT(rt, it->res_obj);
        js_free_rt(rt, it);
    }
}

static void js_iterator_helper_mark(JSRuntime *rt, JSValueConst val,
                                   JS_MarkFunc *mark_func)
{
    JSObject *p = JS_VALUE_GET_OBJ(val);
    JSIteratorHelperData *it = p->u.iterator_helper_data;
    if (it) {
        JS_MarkValue(rt, it->obj, mark_func);
        JS_MarkValue(rt, it->func, mark_func);
        JS_MarkValue(rt, it->next, mark_func);
        JS_MarkValue(rt, it->inner, mark_func);
        JS_MarkValue(rt, it->inner_next, mark_func);
        JS_MarkValue(rt, it->cb_value, mark_func);
        JS_MarkValue(rt, it->res_obj, mark_func);
    }
}

/* Plain-iterator (non-generator source) path for a lazy Iterator Helper .next(): a plain .next() call does not
   suspend, so a C loop here is NOT drive-to-completion. A GENERATOR source is routed onto the tramp before reaching
   here; one that slips through hits the js_generator_next DFAIL. Keeps the recognition identity. */
static const JSCFunctionListEntry js_iterator_funcs[] = {
    JS_CFUNC_DEF("concat", 0, js_iterator_concat ),
    JS_CFUNC_CONSUME_DEF("from", 1, ITERCONS_ITERFROM ),
};

/* Iterator.prototype eager terminals. Every real call is intercepted at the call site and run as an
   ITERCONS_ITERTERM consume on the tramp (do_iterterm_tramp), so the iterator — commonly a GENERATOR — suspends and
   resumes like any other flow. This function exists to give each terminal an ADDRESS the recognition matches, and to
   perform the argument validation the spec does before GetIteratorDirect. Reaching the drive below means an
   un-routed off-tramp call: a should-never-happen to route at its root, never a C loop. */
/* DELETED: js_iterator_proto_terminal. Its body was the receiver check, the callback check and a DFAIL; the
   first is the dispatch's, the second the arm's — where it can still close the iterator — and with the walk
   declared at each definition no pointer names it. */

static const JSCFunctionListEntry js_iterator_proto_funcs[] = {
    /* LAZY helpers create a helper object; its .next() drives the source on the tramp. The EAGER terminals consume
       the iterator to completion — they run as ITERCONS_ITERTERM on the tramp (do_iterterm_tramp), never a C loop. */
    JS_CFUNC_STEP_DEF("drop", 1, STEPDEF_ITER_DROP ),
    JS_CFUNC_STEP_DEF("take", 1, STEPDEF_ITER_TAKE ),
    JS_CFUNC_STEP_DEF("map", 1, STEPDEF_ITER_MAP ),
    JS_CFUNC_STEP_DEF("filter", 1, STEPDEF_ITER_FILTER ),
    JS_CFUNC_STEP_DEF("flatMap", 1, STEPDEF_ITER_FLATMAP ),
    JS_CFUNC_CONSUME_DEF("toArray", 0, ITERCONS_ITERTERM_BASE + ITERTERM_TOARRAY ),
    JS_CFUNC_CONSUME_DEF("forEach", 1, ITERCONS_ITERTERM_BASE + ITERTERM_FOREACH ),
    JS_CFUNC_CONSUME_DEF("reduce", 1, ITERCONS_ITERTERM_BASE + ITERTERM_REDUCE ),
    JS_CFUNC_CONSUME_DEF("some", 1, ITERCONS_ITERTERM_BASE + ITERTERM_SOME ),
    JS_CFUNC_CONSUME_DEF("every", 1, ITERCONS_ITERTERM_BASE + ITERTERM_EVERY ),
    JS_CFUNC_CONSUME_DEF("find", 1, ITERCONS_ITERTERM_BASE + ITERTERM_FIND ),
    JS_CFUNC_DEF("[Symbol.dispose]", 0, js_iterator_proto_dispose ),
    JS_CFUNC_DEF("[Symbol.iterator]", 0, js_iterator_proto_iterator ),
    JS_CGETSET_STEP_DEF("[Symbol.toStringTag]", js_iterator_proto_get_toStringTag, STEPDEF_ITER_SET_TAG),
};

